// Cibles du module Quest : types NPC / box réclamés par les quêtes actives
// non terminées (objectifs tuer/collecter). "*" = tout type accepté.
function botQuestTargets() {
  const npcs = new Set();
  const boxes = new Set();
  try {
    for (const [id, prog] of Object.entries(questState.active || {})) {
      const q = QUEST_DEFINITIONS.find(item => item.id === id);
      if (!q) continue;
      let objs = [];
      try { objs = getQuestObjectives(q); } catch { continue; }
      for (const o of objs) {
        if (Number(prog?.[o.id] || 0) >= o.amount) continue;
        if (o.kind === "kill") npcs.add(String(o.type));
        else if (o.kind === "collect") boxes.add(String(o.type));
      }
    }
  } catch {}
  return { npcs, boxes };
}

// Plus proche NPC de quête (priorité DarkBot puis distance).
// Visibilité "joueur normal" pour le bot : rayon capteurs (1800 m en zone,
// illimité en gate), lock conservé, NPC qui nous attaque toujours visible.
// Utilisé par les recherches de cibles (pas de wallhack map-wide).
function botNpcVisible(e) {
  try {
    let locked = null;
    try { locked = Target.get(); } catch {}
    return shouldDetectNpc(player, e, NPC_SENSOR_RANGES.visibility, locked);
  } catch { return true; }
}

// NPC coincé dans un mur (maps BL) : le bot l'ignore. Marge = rayon NPC
// (+ un peu) pour ne pas viser un centre englouti dans le caillou.
// Hors map zone ou sans murs : jamais bloqué.
function botNpcInWall(e) {
  try {
    if (!isZoneMap || !Array.isArray(zoneWalls) || !zoneWalls.length) return false;
    if (!e) return false;
    const m = Math.max(0, Number(e.r) || 18);
    return isPointInWall(Number(e.x) || 0, Number(e.y) || 0, zoneWalls, m);
  } catch { return false; }
}

// Bannissement court d'un NPC en mur : évite de re-locker aussitôt la même
// cible inatteignable (le filtre live suffit en patrouille, mais le lock
// persistant doit être cassé explicitement). Clé = id NPC, valeur = now ms.
function botNpcWallBanActive(id) {
  try {
    const ban = Bot.npcWallBan;
    if (!ban || typeof ban !== "object") return false;
    const until = Number(ban[String(id)] || 0);
    if (!(until > Date.now())) {
      if (until) { try { delete ban[String(id)]; } catch {} }
      return false;
    }
    return true;
  } catch { return false; }
}

function botNpcBanWall(e, ms = 8000) {
  try {
    if (!e || e.id == null) return;
    if (!Bot.npcWallBan || typeof Bot.npcWallBan !== "object") Bot.npcWallBan = {};
    Bot.npcWallBan[String(e.id)] = Date.now() + Math.max(1000, Number(ms) || 8000);
  } catch {}
}

function botNpcSelectable(e) {
  if (!e || Number(e.hp) <= 0) return false;
  if (e.isPetTarget) return false;
  try { if (!Bot.npcAllow.has(String(e.type))) return false; } catch { return false; }
  if (!botNpcVisible(e)) return false;
  if (botNpcInWall(e)) return false;
  try { if (e.id != null && botNpcWallBanActive(e.id)) return false; } catch {}
  return true;
}

function botNearestQuestNpc(set) {
  let best = null;
  let bestD2 = Infinity;
  const any = set.has("*");
  for (const e of enemies) {
    if (!e || Number(e.hp) <= 0) continue;
    if (e.isPetTarget) continue;
    if (!Bot.npcAllow.has(String(e.type))) continue;
    if (!any && !set.has(String(e.type))) continue;
    // Pas de wallhack : comme un joueur, le bot ne voit que dans son rayon
    // (lock conservé : la cible engagée reste suivie).
    if (!botNpcVisible(e)) continue;
    // NPC dans un mur : ignoré (inatteignable, pas de glitch contre le mur).
    if (botNpcInWall(e)) continue;
    try { if (e.id != null && botNpcWallBanActive(e.id)) continue; } catch {}
    const d2 = dist2(player.x, player.y, e.x, e.y);
    const pr = botNpcPrio(e.type);
    const bpr = best ? botNpcPrio(best.type) : -1;
    if (!best || pr > bpr || (pr === bpr && d2 < bestD2)) { bestD2 = d2; best = e; }
  }
  return best ? { npc: best, d2: bestD2 } : null;
}

function botNearestQuestBox(set) {
  const found = nearestSpatialCollectable(player.x, player.y, (c) => c
    && Bot.boxAllow.has(String(c.type)) && set.has(String(c.type)), Bot.boxRadius);
  return found ? { box: found.item, d2: found.d2 } : null;
}

// Plus proche NPC vivant (module Galaxy Gates : vagues imposées, pas de filtre).
function botNearestAnyNpc() {
  const found = nearestSpatialNpc(player.x, player.y,
    (e) => e && Number(e.hp) > 0 && !e.isPetTarget);
  return found ? { npc: found.item, d2: found.d2 } : null;
}

function botNearestNpc() {
  let best = null;
  let bestD2 = Infinity;
  for (const e of enemies) {
    if (!e || Number(e.hp) <= 0) continue;
    if (e.isPetTarget) continue;
    if (!Bot.npcAllow.has(String(e.type))) continue;
    // Pas de wallhack : comme un joueur, le bot ne voit que dans son rayon
    // (lock conservé : la cible engagée reste suivie).
    if (!botNpcVisible(e)) continue;
    // NPC dans un mur : ignoré (inatteignable, pas de glitch contre le mur).
    if (botNpcInWall(e)) continue;
    try { if (e.id != null && botNpcWallBanActive(e.id)) continue; } catch {}
    const d2 = dist2(player.x, player.y, e.x, e.y);
    const pr = botNpcPrio(e.type);
    const bpr = best ? botNpcPrio(best.type) : -1;
    if (!best || pr > bpr || (pr === bpr && d2 < bestD2)) { bestD2 = d2; best = e; }
  }
  return best ? { npc: best, d2: bestD2 } : null;
}

// Distance pure pour le choix mixte "Le plus proche". Les priorites par
// type de NPC restent reservees au choix "NPC en priorite".
function botNearestNpcByDistance() {
  const found = nearestSpatialNpc(player.x, player.y, (e) => e
    && Number(e.hp) > 0 && !e.isPetTarget && Bot.npcAllow.has(String(e.type))
    && botNpcVisible(e) && !botNpcInWall(e)
    && !(e.id != null && botNpcWallBanActive(e.id)));
  return found ? { npc: found.item, d2: found.d2 } : null;
}

// La portee d'engagement est toujours notre portee laser reelle.
function botEngageRange() {
  try { return Math.max(0, Number(playerRange) || 0); } catch { return 0; }
}
// Le bot ne fait face et n'engage le combat qu'à partir de cette distance.
// Au-delà (navigation, contournement de murs), il regarde où il va vraiment.
const BOT_FACE_RANGE = 1400;
function botEngageStartRange() {
  return Math.min(BOT_FACE_RANGE, Math.max(80, botEngageRange()));
}

// NPC tuable le plus proche DANS la portee (selection + priorites).
function botNearestNpcInRange(maxD) {
  let best = null;
  let bestD2 = Infinity;
  const lim2 = maxD > 0 ? maxD * maxD : Infinity;
  const candidates = Number.isFinite(lim2) ? spatialNpcsNear(player.x, player.y, maxD) : enemies;
  for (const e of candidates) {
    if (!e || Number(e.hp) <= 0) continue;
    if (e.isPetTarget) continue;
    if (!Bot.npcAllow.has(String(e.type))) continue;
    // Pas de wallhack : rayon capteurs comme un joueur.
    if (!botNpcVisible(e)) continue;
    // NPC dans un mur : ignoré (inatteignable, pas de glitch contre le mur).
    if (botNpcInWall(e)) continue;
    try { if (e.id != null && botNpcWallBanActive(e.id)) continue; } catch {}
    const d2 = dist2(player.x, player.y, e.x, e.y);
    if (d2 > lim2) continue;
    const pr = botNpcPrio(e.type);
    const bpr = best ? botNpcPrio(best.type) : -1;
    if (!best || pr > bpr || (pr === bpr && d2 < bestD2)) { bestD2 = d2; best = e; }
  }
  return best;
}

// Munition configuree pour ce NPC (retombe sur X1 si stock vide).
function botApplyNpcAmmo(npc) {
  const current = String(player.ammo.active || "").toLowerCase();
  if (Bot.x6Armed || (current === "sab" && Bot.sabPrev)) return;
  const wantAmmo = Bot.npcAmmo[String(npc.type)] || "x1";
  if (wantAmmo && AMMO[wantAmmo] && player.ammo.active !== wantAmmo) {
    try { setAmmo(wantAmmo); } catch {}
  }
}

// Munitions speciales auto en combat : SAB jusqu'à ce que le bouclier soit
// VIDE (plus une miette) puis retour aux lasers, X6 en burst des que son
// cooldown est pret. Ne coupe jamais l'attaque (switch differents uniquement).
function botAutoSpecialAmmo(npc, d, engageMax) {
  if (!npc || Number(npc.hp) <= 0 || player.dead || !started) return;
  const cur = String(player.ammo.active || "x1").toLowerCase();
  const inRange = d <= engageMax;
  const shMax = Math.max(0, Number(npc.shMax) || 0);
  const shRatio = shMax > 0 ? Math.max(0, Number(npc.sh) || 0) / shMax : 0;
  const shieldUp = shMax > 0 && shRatio > 0.02;

  // X6 : burst des que pret et a portee (prioritaire sur le SAB, mais sans
  // voler son ticket de retour : si on est en plein SAB, on y revient après).
  const npcAutoX6 = Bot.npcX6[String(npc.type)] === true;
  const npcAutoSab = Bot.npcSab[String(npc.type)] === true;
  const configuredLaser = Bot.npcAmmo[String(npc.type)] || "x1";
  if (!npcAutoSab && cur === "sab" && !Bot.x6Armed) {
    Bot.sabPrev = "";
    Bot.x6BackToSab = false;
    try { startAttack(configuredLaser); } catch {}
    return;
  }
  if (npcAutoX6 && inRange && !Bot.x6Armed && cur !== "x6"
    && ammoCount("x6") > 0) {
    try {
      if (rsbLikeCooldown("x6") <= 0) {
        if (cur === "sab" && shieldUp) Bot.x6BackToSab = true;
        else Bot.specialPrev = cur;
        Bot.x6Armed = true;
        Bot.x6ArmedAt = Date.now();
        try { startAttack("x6"); } catch {}
        return;
      }
    } catch {}
  }
  // Salve X6 partie (cooldown actif) ou delai depasse : retour au precedent
  // (ou au SAB en cours si le burst l'avait interrompu).
  if (Bot.x6Armed) {
    let fired = false;
    try { fired = rsbLikeCooldown("x6") > 0; } catch {}
    if (fired || Date.now() - Number(Bot.x6ArmedAt || 0) > 3000) {
      Bot.x6Armed = false;
      let back = "";
      if (Bot.x6BackToSab === true) {
        Bot.x6BackToSab = false;
        back = npcAutoSab && shieldUp ? "sab" : configuredLaser;
      } else {
        back = Bot.specialPrev && AMMO[Bot.specialPrev] ? Bot.specialPrev : "";
        Bot.specialPrev = "";
      }
      if (back && back !== String(player.ammo.active || "").toLowerCase()) {
        try { startAttack(back); } catch {}
      }
      return;
    }
    return; // salve en cours : on ne touche a rien d'autre.
  }

  // SAB : on vide le bouclier jusqu'au bout, puis retour aux lasers.
  // (Jamais pendant un burst X6 : la garde x6Armed ci-dessus a déjà filtré.)
  if (npcAutoSab && AMMO.sab && cur !== "x6") {
    if (cur !== "sab" && shieldUp && ammoCount("sab") > 0) {
      Bot.sabPrev = cur;
      try { startAttack("sab"); } catch {}
      return;
    }
    if (cur === "sab" && (!shieldUp || ammoCount("sab") <= 0)) {
      const back = Bot.sabPrev && AMMO[Bot.sabPrev] ? Bot.sabPrev : "";
      Bot.sabPrev = "";
      if (back && back !== String(player.ammo.active || "").toLowerCase()) {
        try { startAttack(back); } catch {}
      }
    }
  }
}

function botClearSpecialAmmo() {
  const current = String(player.ammo.active || "").toLowerCase();
  let back = "";
  if (current === "x6" && (Bot.x6Armed || Bot.specialPrev || Bot.x6BackToSab)) {
    back = Bot.x6BackToSab ? Bot.sabPrev : Bot.specialPrev;
  } else if (current === "sab" && Bot.sabPrev) {
    back = Bot.sabPrev;
  }
  if (back && AMMO[back] && back !== "x6" && back !== "sab") {
    try { setAmmo(back); } catch {}
  }
  Bot.specialPrev = "";
  Bot.sabPrev = "";
  Bot.x6BackToSab = false;
  Bot.x6Armed = false;
  Bot.x6ArmedAt = 0;
}

// NPC a engager EN PARALLELE d'une collecte (sans toucher au mouvement) :
// cible verrouillee d'abord (respect du lock), sinon le plus proche a portee.
// Module quest : uniquement les NPC de quete. Autres modes que both : rien.
function botConcurrentNpc(engageMax, locked) {
  const lim2 = engageMax * engageMax;
  const okTarget = (e) => {
    if (!e || e.isPetTarget || Number(e.hp) <= 0) return false;
    try { if (!enemies.includes(e)) return false; } catch { return false; }
    if (botNpcInWall(e)) return false;
    try { if (e.id != null && botNpcWallBanActive(e.id)) return false; } catch {}
    try { return dist2(player.x, player.y, e.x, e.y) <= lim2; } catch { return false; }
  };
  try {
    if (Bot.mode !== "both") return null;
    if (locked && Bot.npcAllow.has(String(locked.type)) && okTarget(locked)) return locked;
    return botNearestNpcInRange(engageMax);
  } catch { return null; }
}

function botNpcLockKey(npc) {
  if (!npc) return null;
  if (npc._netUid != null) return `net:${String(npc._netUid)}:${Number(npc._netSeq) || 0}`;
  if (npc.universeUid != null) return `universe:${String(npc.universeUid)}`;
  return npc.id != null ? `local:${String(npc.id)}` : null;
}

function botNpcHasLockKey(npc, key) {
  if (!npc || key == null) return false;
  const stableKey = botNpcLockKey(npc);
  // Compatibilite avec une cible conservee avant cette mise a jour.
  return stableKey === String(key) || String(npc.id) === String(key);
}

function botLockNpc(npc) {
  const key = botNpcLockKey(npc);
  if (!key) return;
  Bot.combatTargetId = key;
  Bot.lastNpcId = npc.id;
  Bot.lastNpcKey = key;
}

function botTargetIsNpc(npc) {
  try { return botNpcLockKey(Target.get()) === botNpcLockKey(npc); } catch { return false; }
}

// Verrouille + tire sur un NPC SANS toucher au mouvement (collecte simultanee).
function botEngageNpc(npc) {
  if (!npc || Number(npc.hp) <= 0) return null;
  try { if (!botTargetIsNpc(npc)) Target.set(npc); } catch {}
  botApplyNpcAmmo(npc);
  let d = 0;
  try { d = Math.hypot(npc.x - player.x, npc.y - player.y); } catch {}
  const engageMax = botEngageRange();
  if (!attackActive && d <= botEngageStartRange()) { try { startAttack(); } catch {} }
  else if (attackActive && d > engageMax + 20) { try { stopAttack(); } catch {} }
  try { botAutoSpecialAmmo(npc, d, engageMax); } catch {}
  botLockNpc(npc);
  return npc;
}

// Box a ramasser AU PASSAGE pendant un combat : autorisee, dans le rayon de
// detour ET plus proche que le NPC. Module quest : box de quete uniquement.
const BOT_GRAB_RADIUS = 380;
function botGrabBoxForFight(npc, standD) {
  try {
    if (Bot.mode !== "both" || Bot.priority !== "npc" || !npc) return null;
    if ((Bot.grabCd || 0) > 0) return null;
    const grabR2 = BOT_GRAB_RADIUS * BOT_GRAB_RADIUS;
    const currentNpcD = Math.hypot(player.x - npc.x, player.y - npc.y);
    // Tant que le tir n'est pas reellement etabli, poursuite pure. Au bord de
    // portee une box ne doit jamais etre acceptee puis rejetee au tick suivant
    // parce que le NPC passif s'est eloigne de quelques metres.
    if (!attackActive || currentNpcD > botEngageRange()) {
      Bot.lastBoxId = null;
      return null;
    }
    const shootRange = Math.max(0, Number(npc.shootRange) || Number(NPC_TYPES[npc.type]?.shootRange) || 0);
    const safeAtBox = shootRange > 0 ? shootRange + 70 : Math.max(180, standD - 25);
    const routeX = moveTarget.active ? Number(moveTarget.x) : player.x;
    const routeY = moveTarget.active ? Number(moveTarget.y) : player.y;
    const segX = routeX - player.x, segY = routeY - player.y;
    const segL2 = segX * segX + segY * segY;
    // Une fois la petite deviation commencee, terminer CETTE box. Sans ce
    // verrou, deux box voisines deviennent tour a tour "la plus proche" et
    // font alterner le point de mouvement a chaque tick.
    if (Bot.lastBoxId != null) {
      const current = collectables.find((c) => c && String(c.id) === String(Bot.lastBoxId));
      if (current && Bot.boxAllow.has(String(current.type))) {
        const currentD2 = dist2(player.x, player.y, current.x, current.y);
        const currentNpcD = Math.hypot(current.x - npc.x, current.y - npc.y);
        const releaseR = BOT_GRAB_RADIUS + 120;
        const stickySafeAtBox = shootRange > 0 ? safeAtBox : Math.max(140, safeAtBox - 60);
        if (currentD2 <= releaseR * releaseR && currentNpcD >= stickySafeAtBox) {
          return { box: current, d2: currentD2 };
        }
      }
      // Disparue, trop loin ou devenue dangereuse : seulement ici une autre
      // box peut etre choisie.
      Bot.lastBoxId = null;
    }
    let best = null;
    let bestD2 = Infinity;
    for (const c of spatialCollectablesNear(player.x, player.y, BOT_GRAB_RADIUS)) {
      if (!c) continue;
      if (!Bot.boxAllow.has(String(c.type))) continue;
      const d2 = dist2(player.x, player.y, c.x, c.y);
      if (d2 > grabR2) continue;
      const boxNpcD = Math.hypot(c.x - npc.x, c.y - npc.y);
      if (boxNpcD < safeAtBox) continue;
      let routeDistance = Math.sqrt(d2);
      if (segL2 > 1) {
        const t = clamp(((c.x - player.x) * segX + (c.y - player.y) * segY) / segL2, 0, 1);
        routeDistance = Math.hypot(c.x - (player.x + segX * t), c.y - (player.y + segY * t));
      }
      const onRoute = routeDistance <= 170;
      const slightRetreat = d2 <= 300 * 300 && boxNpcD >= currentNpcD - 20;
      if (!onRoute && !slightRetreat) continue;
      if (d2 < bestD2) { bestD2 = d2; best = c; }
    }
    return best ? { box: best, d2: bestD2 } : null;
  } catch { return null; }
}

function botNearestBox() {
  const found = nearestSpatialCollectable(player.x, player.y,
    (c) => c && Bot.boxAllow.has(String(c.type)), Bot.boxRadius);
  return found ? { box: found.item, d2: found.d2 } : null;
}

// Itinéraire physique entre deux maps via le graphe des portails (BFS).
// Retourne [from, ..., to] ou null (index pas prêt ou aucune route).
function botFindRoute(from, to) {
  from = String(from || "").toLowerCase();
  to = String(to || "").toLowerCase();
  if (!from || !to) return null;
  if (from === to) return [to];
  const idx = botPortalIndex;
  if (!idx) return null;
  const prev = new Map([[from, null]]);
  const queue = [from];
  while (queue.length) {
    const cur = queue.shift();
    for (const nxt of idx[cur] || []) {
      if (prev.has(nxt)) continue;
      prev.set(nxt, cur);
      if (nxt === to) {
        const path = [to];
        let c = to;
        while (prev.get(c)) { c = prev.get(c); path.unshift(c); }
        return path;
      }
      queue.push(nxt);
    }
  }
  return null;
}

// Onglet Galaxy : switch adouci vers le plus proche en gate.
// Délai minimum entre deux switchs volontaires + la nouvelle cible doit être
// nettement plus proche (évite l'oscillation A↔B qui mitraille les cooldowns).
const BOT_GG_SWITCH_DELAY = 1.5;
const BOT_GG_SWITCH_CLOSER2 = 0.72; // (0.85)^2 : ~15 % plus proche en distance.

// Formation / config de fin : UNIQUEMENT dès que le Cubikon est mort
// (complétion en cours), jusqu'au renvoi sur la map mère. Pas pendant la
// vague Cubikon : le combat se fait en formation d'attaque normale.
function botGalaxyIsFinishWave() {
  try {
    return gateCompletionPending === true;
  } catch { return false; }
}

function botApplyGalaxyFinishFormation() {
  if (!botGalaxyIsFinishWave()) return;
  try {
    if (Bot.ggFinishForm) botApplyFormation(Bot.ggFinishForm);
  } catch {}
  try {
    if (Bot.ggFinishCfg === "1" || Bot.ggFinishCfg === "2") botApplyConfig(Number(Bot.ggFinishCfg));
  } catch {}
}

// Excursion radiation (gate + map) : quand le kite est plaqué contre un bord
// (cible clampée ≈ sur place) avec une menace proche, on autorise une sortie
// courte hors map pour esquiver et se replacer au lieu de rester fixe contre
// le mur ou coincé dans un coin. 5 s gratuites sans dégâts (on reste sous
// ~3,5 s d'exposition, ~500 m de profondeur max), exposition remise à 0 dès
// la rentrée, et les NPC suivent peu/nul dehors : respiration garantie.
function botGateKiteTarget(rawX, rawY, threatClose) {
  void threatClose;
  return { x: clamp(rawX, 120, WORLD.w - 120), y: clamp(rawY, 120, WORLD.h - 120) };
  /* Ancienne excursion volontaire en radiation desactivee.
  const inside = { x: clamp(rawX, 120, WORLD.w - 120), y: clamp(rawY, 120, WORLD.h - 120) };
  try {
    let outside = false, exp = 0;
    try { outside = playerIsOutsideWorld(); exp = Number(radiationSystem?.state?.exposure) || 0; } catch {}
    if (outside) {
      // Dehors : on y reste brièvement si menace proche et exposition faible,
      // sinon on rentre aussitôt.
      if (threatClose && exp < 2.5) {
        return { x: clamp(rawX, -500, WORLD.w + 500), y: clamp(rawY, -500, WORLD.h + 500) };
      }
      return inside;
    }
    if (!threatClose) return inside;
    const blocked = Math.hypot(inside.x - player.x, inside.y - player.y) < 150;
    if (!blocked || exp > 3.5) return inside;
    return { x: clamp(rawX, -500, WORLD.w + 500), y: clamp(rawY, -500, WORLD.h + 500) };
  } catch { return inside; } */
}

// ✅ Clamp des cibles de mouvement du bot en combat : en map (zone), on
// autorise la marge de radiations au lieu de rester plaqué contre le mur ou
// coincé dans un coin. En gate, on reste strictement dans la carte.
function botClampMoveTarget(x, y) {
  return { x: clamp(x, 120, WORLD.w - 120), y: clamp(y, 120, WORLD.h - 120) };
}

// Ordre de mouvement throttlé (combat uniquement) : le tick tourne à chaque
// frame, mais on ne RE-clique que si le nouveau point a bougé de 50 m+ ou si
// la cible a changé. Entre deux ordres le vaisseau file en ligne droite :
// fini les clics à foison tout autour et le glitch sur place. Le tag =
// l'id du NPC : changer de cible force un ordre frais.
function botOrderMove(x, y, tag) {
  x = Math.round(Number(x) || 0);
  y = Math.round(Number(y) || 0);
  const now = performance.now();
  if (moveTarget.active && Bot.moveTag === tag) {
    const dx = x - moveTarget.x, dy = y - moveTarget.y;
    const remaining2 = dist2(player.x, player.y, moveTarget.x, moveTarget.y);
    if (dx * dx + dy * dy < 900 && remaining2 > 6400 && now - Bot.moveOrderedAt < 220) return;
  }
  for (const [id, key] of [["botPetEnabled", "petEnabled"], ["botPetAutoFuel", "petAutoFuel"]]) {
    const box = document.getElementById(id);
    if (!box) continue;
    box.checked = Bot[key] === true;
    if (!box.dataset.wired) {
      box.dataset.wired = "1";
      box.addEventListener("change", () => {
        Bot[key] = box.checked;
        botSaveConfig();
        if (Bot.active) botApplyPetMode();
      });
    }
  }
  Bot.moveTag = tag;
  Bot.moveOrderedAt = now;
  moveTarget.active = true;
  moveTarget.x = x;
  moveTarget.y = y;
}

// Prochain pas du bot : le trajet contourne les murs sans modifier l'ordre final.
function botMovementStep(dt) {
  if (isPlayerMovementLocked() || !Bot.active || !moveTarget.active || player.dead || pointer.down
    || performance.now() - Number(Bot.manualT || 0) < 2500
    || !isZoneMap || !zoneWalls?.length) {
    Bot.wallSteer = null;
    return moveTarget;
  }
  let combatNpc = null;
  // La poursuite conserve son trajet meme lorsque le contour passe hors
  // de portee et coupe les tirs. Collecte, fuite et voyage gardent leur ordre.
  if (Bot.combatMoveTargetId != null && Bot.combatMoveTargetId === Bot.combatTargetId) {
    combatNpc = enemies.find(e => botNpcHasLockKey(e, Bot.combatMoveTargetId) && Number(e.hp) > 0 && !e.isPetTarget) || null;
    if (botNpcInWall(combatNpc)) combatNpc = null;
  }
  Bot.wallSteer ||= {};
  const steer = computeBotWallMove({ player, target: moveTarget, npc: combatNpc, walls: zoneWalls,
    bounds: { minX: 100, minY: 100, maxX: WORLD.w - 100, maxY: WORLD.h - 100 }, state: Bot.wallSteer, dt });
  if (steer.unreachable) {
    // Un objectif isole par les murs ne doit pas retenir le bot sur place.
    if (Bot.wallSteer.unreachableT > 0.75 && playerSlowMult(player) > 0) {
      if (combatNpc) {
        botNpcBanWall(combatNpc);
        try { stopAttack(); Target.clear(); } catch {}
        Bot.combatTargetId = null; Bot.lastNpcId = null; Bot.lastNpcKey = null; Bot.steering = null;
      }
      moveTarget.active = false; Bot.moveTag = null; Bot.roamT = 0;
    }
    return { active: false, x: player.x, y: player.y };
  }
  if (!steer.detour) return moveTarget;
  if (steer.adjusted && Math.hypot(steer.x - player.x, steer.y - player.y) <= 0.5) {
    moveTarget.active = false;
    return moveTarget;
  }
  return { active: true, x: steer.x, y: steer.y };
}

// Conserve le rayon de combat meme pres d'un bord. Un clamp direct peut
// rabattre un point exterieur juste a cote du NPC ; on cherche alors le point
// valide le plus proche sur le meme cercle.
function botClampCombatTarget(npc, preferredX, preferredY, standD) {
  const first = botClampMoveTarget(preferredX, preferredY);
  if (Math.hypot(first.x - npc.x, first.y - npc.y) >= standD - 6) return first;
  const preferredAngle = Math.atan2(preferredY - npc.y, preferredX - npc.x);
  let best = first;
  let bestScore = Infinity;
  let bestRadius = Math.hypot(first.x - npc.x, first.y - npc.y);
  for (let i = 0; i < 32; i++) {
    const offset = (Math.ceil(i / 2) * (i % 2 ? 1 : -1)) * (TAU / 32);
    const angle = preferredAngle + offset;
    const rawX = npc.x + Math.cos(angle) * standD;
    const rawY = npc.y + Math.sin(angle) * standD;
    const candidate = botClampMoveTarget(rawX, rawY);
    const radius = Math.hypot(candidate.x - npc.x, candidate.y - npc.y);
    if (radius > bestRadius) { bestRadius = radius; best = candidate; }
    if (radius < standD - 6) continue;
    const score = Math.abs(offset) + Math.hypot(candidate.x - player.x, candidate.y - player.y) / 100000;
    if (score < bestScore) { bestScore = score; best = candidate; }
  }
  return best;
}

// ✅ Kiting de combat PARTOUT (map + GG) : approche hors portée, recul si
// trop près, sinon répulsion de TOUS les NPC proches + dérive tangentielle.
// Jamais de camping, jamais de colle : le vaisseau est toujours en mouvement.
function botKiteCombatMove(npc, d, standD, dt) {
  if (!npc || Number(npc.hp) <= 0) { moveTarget.active = false; Bot.moveTag = null; return; }
  const steering = computeBotCombatMove({
    player,
    npc,
    range: Math.max(140, Number(playerRange) || 0),
    desiredDistance: standD,
    bounds: {
      minX: 0,
      minY: 0,
      maxX: WORLD.w,
      maxY: WORLD.h,
      margin: 120,
    },
    state: Bot.steering?.npcId === npc.id ? Bot.steering : {},
    dt,
    // Orbite décollée des murs (pas de frôlement/glitch contre les cailloux).
    walls: isZoneMap && Array.isArray(zoneWalls) && zoneWalls.length ? zoneWalls : null,
    shipRadius: player.r || 18,
  });
  Bot.steering = { ...steering.state, npcId: npc.id };
  botOrderMove(steering.x, steering.y, npc.id);
  Bot.combatMoveTargetId = Bot.combatTargetId;
  return;

  /* Legacy steering kept temporarily below for easy comparison while the
     deterministic controller above is exercised by browser smoke tests. */
  void dt;
  const ax = d > 1 ? (player.x - npc.x) / d : 1;
  const ay = d > 1 ? (player.y - npc.y) / d : 0;
  // Trop pres : recule au rayon en biaisant sur le côté (pas de ligne
  // droite, pas de demi-tour sec) — le strafe reprend juste après.
  if (d < standD - 12 && d > 0.01) {
    const tx = -ay, ty = ax;
    const need = (standD - d) + 150;
    const tgt = botClampMoveTarget(player.x + ax * need + tx * 200, player.y + ay * need + ty * 200);
    botOrderMove(tgt.x, tgt.y, npc.id);
    return;
  }
  if (d > Math.max(80, playerRange + 20)) {
    // Hors de portée : approche décalée (point à standD, pas le centre).
    const tgt = botClampMoveTarget(npc.x + ax * standD, npc.y + ay * standD);
    botOrderMove(tgt.x, tgt.y, npc.id);
    return;
  }
  let kx = 0, ky = 0;
  let closestD = Infinity, closestX = 0, closestY = 0;
  // Sur map : comme en GG, on ne réagit qu'aux NPC qui nous chassent (+ la
  // cible). Les passants qui traversent à 1600 m ne doivent pas faire
  // glitcher le strafe ni déclencher la fuite contact. En GG tout le monde
  // nous chasse de toute façon : comportement strictement identique.
  const mapMode = !(Bot.module === "galaxy" && rules?.mode === "gate");
  for (const e of enemies) {
    if (!e || Number(e.hp) <= 0) continue;
    if (mapMode && e !== npc) {
      let engaging = false;
      try { engaging = typeof npcIsEngagingPlayer === "function" && npcIsEngagingPlayer(e) === true; } catch {}
      if (!engaging) continue;
    }
    const ex = player.x - e.x, ey = player.y - e.y;
    const ed = Math.hypot(ex, ey);
    if (ed < closestD) { closestD = ed; closestX = ex; closestY = ey; }
    const KR = 1600;
    if (ed < KR && ed > 1) {
      const w = 1 - ed / KR;
      const push = w * w * (e === npc ? 420 : 1200);
      kx += (ex / ed) * push;
      ky += (ey / ed) * push;
    }
  }
  if (closestD < 150 && closestD > 0.01) {
    // Contact : fuite franche à ~45° du plus proche (radial + latéral).
    const ax = closestX / closestD, ay = closestY / closestD;
    kx = ax * 800 + -ay * 800;
    ky = ay * 800 + ax * 800;
  }
  const kl = Math.hypot(kx, ky);
  if (kl < 60) {
    moveTarget.active = false; // rien à fuir : on tient et on tire
  } else {
    const tx = -ky / kl, ty = kx / kl;
    const step = Math.min(kl, 800);
    let rawX = player.x + kx / kl * step + tx * 350;
    let rawY = player.y + ky / kl * step + ty * 350;
    // Une esquive secondaire ne peut jamais choisir un point situe a
    // l'interieur du rayon de combat de la cible prioritaire.
    const ndx = rawX - npc.x, ndy = rawY - npc.y;
    const nd = Math.hypot(ndx, ndy);
    if (nd > 0.01 && nd < standD) {
      rawX = npc.x + ndx / nd * standD;
      rawY = npc.y + ndy / nd * standD;
    }
    const tgt = botGateKiteTarget(rawX, rawY, closestD < 600);
    botOrderMove(tgt.x, tgt.y, npc.id);
  }
}

// Spinner auto hors gate (toutes les 100 ms) : multiplicateur auto puis
// spins sur l'ensemble Alpha + Beta + Gamma (une seule roue). Le placement
// sur la map est automatique (voir GALAXY_GATES.js) : la 2e GG reste en
// stock 1/1 tant qu'un portail est déjà posé.
function botTickGalaxySpin(dt) {
  if (!Bot.ggSpin || Bot.module !== "galaxy" || rules?.mode === "gate") return false;
  Bot.ggSpinT -= dt;
  Bot.ggUiT -= dt;
  if (Bot.ggSpinT > 0) return false;
  Bot.ggSpinT = 0.1;
  let user = null;
  try { user = account.user || getCurrentUserFull(); } catch { user = null; }
  const st = user?.galaxyGates;
  if (!st) return false;
  // Alpha / Beta / Gamma ne font qu'un (groupe "ensemble") : spinner Alpha.
  // (Delta a sa propre roue, hors bot pour le moment.)
  const gateId = "alpha";
  const ggEnsMult = Number(st.multipliers?.ensemble ?? st.multiplier);
  const ggEnsArmed = (st.multiplierArmed?.ensemble ?? st.multiplierArmed) === true;
  // Multiplicateur auto : on l'arme dès qu'il est disponible (x2+).
  if (Bot.ggAutoMult && ggEnsMult > 1 && ggEnsArmed !== true) {
    try {
      const armed = armCurrentUserGalaxyGateMultiplier(gateId, true);
      if (armed?.ok) {
        account.user = armed.user;
        loadAccountUser();
        renderGalaxyGateWindow("Multiplicateur activé (bot).");
        botLog(`GG ${gateId.toUpperCase()} : multiplicateur x${armed.state?.multipliers?.ensemble ?? armed.state?.multiplier ?? ggEnsMult} activé`);
        user = armed.user;
      }
    } catch {}
  }
  const built = Number(user?.galaxyGates?.built?.[gateId] || 0);
  if (built >= GALAXY_GATE_BUILD_LIMIT) return false;
  const spins = Math.max(1, Math.min(100, Math.floor(Number(Bot.ggSpins) || 1)));
  let result = null;
  try { result = spinCurrentUserGalaxyGate(gateId, spins); } catch { result = null; }
  if (!result) return false;
  if (!result.ok) {
    Bot.status = "Galaxy Gates";
    Bot.target = String(result.error || "Spin impossible").slice(0, 60);
    return true;
  }
  try {
    account.user = result.user;
    loadAccountUser();
    player.credits = result.user.credits;
    player.ammo.x2 = result.user.ammo.x2;
    player.ammo.x3 = result.user.ammo.x3;
    player.ammo.x4 = result.user.ammo.x4;
    player.ammo.sab = result.user.ammo.sab;
    player.ammo.x6 = result.user.ammo.x6;
    player.rockets = player.rockets || {};
    for (const [rocketId, amount] of Object.entries(result.user.rockets || {})) player.rockets[rocketId] = amount;
    updateAmmoUI();
  } catch {}
  const autoPlaced = Array.isArray(result.rewards?.autoDeployed) ? result.rewards.autoDeployed : [];
  const builtNow = Number(result.state?.built?.[gateId] || 0);
  const isBuilt = builtNow >= GALAXY_GATE_BUILD_LIMIT || autoPlaced.length > 0;
  // À 10 passages/s on ne rebuild l'UI et le journal que toutes les ~2 s
  // (ou dès qu'une gate est construite / placée).
  const uiDue = isBuilt || Bot.ggUiT <= 0;
  if (uiDue) {
    Bot.ggUiT = 2;
    try { renderGalaxyGateWindow(`${result.performed} spin(s) auto (ensemble)`); } catch {}
    if (!isBuilt) botLog(`GG spinner auto : +${result.performed} spin(s) (ensemble)`);
  }
  // Sécurité legacy : une vieille sauvegarde avec built=1 + non déployée
  // est posée sur la map (normalement déjà migrée par normalize).
  for (const id of ["alpha", "beta", "gamma"]) {
    if (Number(result.state?.built?.[id] || 0) >= GALAXY_GATE_BUILD_LIMIT && result.state?.deployed?.[id] !== true && result.state?.active !== id) {
      try {
        const dep = deployCurrentUserGalaxyGate(id);
        if (dep?.ok) {
          account.user = dep.user;
          loadAccountUser();
          renderGalaxyGateWindow(`${GALAXY_GATE_DEFINITIONS[id].name} envoyée sur la map (bot).`);
        }
      } catch {}
    }
  }
  for (const id of autoPlaced) botLog(`GG ${String(id).toUpperCase()} placée sur la map — direction le portail`);
  return true;
}

// Retourne la gate à jouer : active en priorité, sinon la première
// construite / déployée de l'ensemble (Alpha → Beta → Gamma).
// Null = rien à entrer pour l'instant.
function botPickReadyGalaxyGate() {
  let st = null;
  try { st = (account.user || getCurrentUserFull())?.galaxyGates; } catch { st = null; }
  if (!st) return null;
  const order = ["alpha", "beta", "gamma"];
  if (st.active && GALAXY_GATE_DEFINITIONS[st.active]) return st.active;
  for (const id of order) {
    if (Number(st.built?.[id] || 0) >= GALAXY_GATE_BUILD_LIMIT || st.deployed?.[id] === true) return id;
  }
  return null;
}

// Hors gate, module Galaxy : vole vers la base mère puis vers le portail GG
// déployé et saute dedans. Retourne true si ce comportement a pris la main.
function botTickGalaxyEnter(dt) {
  if (Bot.module !== "galaxy" || !Bot.ggAutoEnter) return false;
  if (rules?.mode === "gate") return false;
  if (Bot.selling || Bot.fleeing) return false;
  const gateId = botPickReadyGalaxyGate();
  if (!gateId) return false;
  let st = null;
  try { st = (account.user || getCurrentUserFull())?.galaxyGates; } catch { st = null; }
  // Sécurité legacy : pose un stock restant non déployé (migration auto normale).
  if (Number(st?.built?.[gateId] || 0) >= GALAXY_GATE_BUILD_LIMIT && st?.deployed?.[gateId] !== true && st?.active !== gateId) {
    try {
      const dep = deployCurrentUserGalaxyGate(gateId);
      if (dep?.ok) {
        account.user = dep.user;
        loadAccountUser();
        renderGalaxyGateWindow(`${GALAXY_GATE_DEFINITIONS[gateId].name} envoyée sur la map (bot).`);
        botLog(`GG ${gateId.toUpperCase()} déployée — direction le portail`);
      }
    } catch {}
  }
  const user = account.user || getCurrentUserFull();
  const homeMap = String(getFactionHomeMap(user?.faction) || "").toLowerCase();
  const curMap = String(window.__CURRENT_MAP_ID__ || "1-1").toLowerCase();
  Bot.ggJumpCd -= dt;
  botApplyMoveProfile("travel");
  // 1. Rejoindre la base mère (voyage physique portail par portail).
  if (homeMap && curMap !== homeMap) {
    if (!botPortalIndex) {
      Bot.status = "Galaxy Gates";
      Bot.target = `Retour base ${homeMap.toUpperCase()}…`;
      botRefreshHudThrottled(dt);
      return true;
    }
    const route = botFindRoute(curMap, homeMap);
    if (!route) {
      Bot.status = "Galaxy Gates";
      Bot.target = `Base ${homeMap.toUpperCase()} inaccessible`;
      botRefreshHudThrottled(dt);
      return true;
    }
    const nextHop = route[1] || homeMap;
    const portalStep = (zonePortals || []).find((p) => String(p.toMap || "").toLowerCase() === nextHop);
    if (!portalStep) {
      Bot.status = "Galaxy Gates";
      Bot.target = `Portail vers ${nextHop.toUpperCase()} introuvable`;
      botRefreshHudThrottled(dt);
      return true;
    }
    Bot.status = `Galaxy Gates → ${gateId.toUpperCase()}`;
    Bot.target = `Retour base (${Math.round(Math.hypot(portalStep.x - player.x, portalStep.y - player.y))}m)`;
    if (attackActive) { try { stopAttack(); } catch {} }
    try { cancelCollectableTarget(); } catch {}
    moveTarget.active = true;
    moveTarget.x = clamp(portalStep.x, 80, WORLD.w - 80);
    moveTarget.y = clamp(portalStep.y, 80, WORLD.h - 80);
    if (isPlayerNearPortal(portalStep) && mapPortalLock <= 0 && !portalStep.jumping && Bot.ggJumpCd <= 0) {
      Bot.ggJumpCd = 3;
      try { if (startZonePortalJump(portalStep)) botLog(`Galaxy : transit vers ${nextHop.toUpperCase()}`); } catch {}
    }
    botRefreshHudThrottled(dt);
    return true;
  }
  // 2. Sur la base mère : foncer sur le portail GG et sauter dedans.
  const ggPortal = (zonePortals || []).find((p) => String(p.toMap || "").toLowerCase() === gateId);
  if (!ggPortal) {
    Bot.status = "Galaxy Gates";
    Bot.target = `Portail ${gateId.toUpperCase()} introuvable (spinner ?)`;
    botRefreshHudThrottled(dt);
    return true;
  }
  Bot.status = `Galaxy Gates → ${gateId.toUpperCase()}`;
  Bot.target = `Portail GG (${Math.round(Math.hypot(ggPortal.x - player.x, ggPortal.y - player.y))}m)`;
  if (attackActive) { try { stopAttack(); } catch {} }
  try { cancelCollectableTarget(); } catch {}
  try { if (Target.get()) Target.clear(); } catch {}
  moveTarget.active = true;
  moveTarget.x = clamp(ggPortal.x, 80, WORLD.w - 80);
  moveTarget.y = clamp(ggPortal.y, 80, WORLD.h - 80);
  if (isPlayerNearPortal(ggPortal) && mapPortalLock <= 0 && !ggPortal.jumping && Bot.ggJumpCd <= 0) {
    Bot.ggJumpCd = 3;
    try {
      if (startZonePortalJump(ggPortal)) botLog(`Entrée GG ${gateId.toUpperCase()}…`);
      else Bot.target = "Portail GG : spinner requis";
    } catch {}
  }
  botRefreshHudThrottled(dt);
  return true;
}

// Refuge de non-agression le plus proche sur la carte courante. La distance
// est mesuree jusqu'au bord de la zone, pas jusqu'a son centre : une grande
// base proche gagne donc logiquement face a un portail plus eloigne.
function botNearestSafeRefuge(x, y) {
  if (!isZoneMap) return null;
  const candidates = [];
  const add = (kind, label, cx, cy, radius) => {
    cx = Number(cx); cy = Number(cy); radius = Number(radius);
    if (!Number.isFinite(cx) || !Number.isFinite(cy) || !(radius > 0)) return;
    const centerDistance = Math.hypot(x - cx, y - cy);
    const edgeDistance = Math.max(0, centerDistance - radius);
    // Le refuge est choisi par son bord, mais le point d'arrivee reste proche
    // du centre afin de ne pas reparer juste a la limite de protection.
    const centerOffset = Math.min(150, radius * 0.15);
    const nx = centerDistance > 1 ? (x - cx) / centerDistance : 0;
    const ny = centerDistance > 1 ? (y - cy) / centerDistance : 0;
    candidates.push({
      kind, label, cx, cy, radius, edgeDistance,
      x: cx + nx * centerOffset,
      y: cy + ny * centerOffset,
    });
  };

  try {
    for (const portal of getInteractivePortals()) {
      if (!portalProvidesSafety(portal)) continue;
      add("portal", "portail sûr", portal.x, portal.y, DEFAULT_PORTAL_RADIUS + SAFE_ZONE_MARGIN);
    }
  } catch {}
  try {
    if (baseProvidesSafety() && zoneSafe?.zone?.kind === "circle") {
      const z = zoneSafe.zone;
      add("base", getCurrentZoneMapId() === "5-2" ? "base pirate" : "base de faction", z.x, z.y, z.r);
    }
  } catch {}
  try {
    for (const module of zoneSafe?.modules || []) {
      const radius = Number(module?.safeRadius || 0);
      if (!(radius > 0) || !canUseStation(module)) continue;
      add("module", "zone de non-agression", module.x, module.y, radius);
    }
  } catch {}

  candidates.sort((a, b) => a.edgeDistance - b.edgeDistance
    || Math.hypot(x - a.cx, y - a.cy) - Math.hypot(x - b.cx, y - b.cy));
  return candidates[0] || null;
}

function botBlacklightSearch(dt) {
  if (Bot.mode === "collect" || Bot.module === "quest" || !isBlacklightMap()) return null;
  return blacklightSearchTarget({ mapId: currentMapId(), camps: zoneCamps, allowed: Bot.npcAllow,
    world: WORLD, walls: zoneWalls, player, sensorRange: NPC_SENSOR_RANGES.visibility,
    state: Bot.blSearch, dt, failed: Bot.moveTag === "search-bl" && !moveTarget.active });
}

function botQueueCloakAfterKill(npc) {
  const key = botNpcLockKey(npc);
  if (!Bot.active || !Bot.skillCloak || !started || player.dead || !npc
      || !(npc.hp <= 0) || npc._botCloakQueued === key || npc.noRewards || npc.suppressDeathExplosion
      || npc._netPlayer || npc._netPet || (npc._netUid && npc._netKiller == null)
      || performance.now() - Bot.manualT < 2500
      || !botNpcHasLockKey(npc, Bot.lastNpcKey)) return;
  npc._botCloakQueued = key;
  Bot.cloakPendingMap = currentMapId();
  stopAttack();
}

function botTickAutoCloak() {
  if (Bot.cloakPendingMap == null) return false;
  if (!Bot.active || !Bot.skillCloak || !started || player.dead
      || Bot.cloakPendingMap !== currentMapId() || isPlayerCpuCloaked() || isPlayerCloaked()
      || player.credits < CPU_CLOAK_COST) {
    Bot.cloakPendingMap = null;
    return false;
  }
  // Attendre la courte recharge apres le dernier tir avant de reprendre
  // une cible : sinon les nouveaux tirs retarderaient toujours le camouflage.
  if (cloakCd > 0) return true;
  toggleCpuCloak();
  Bot.cloakPendingMap = null;
  if (isPlayerCpuCloaked()) botLog("Camouflage auto après destruction du NPC (30 000 crédits)");
  return true;
}

function botTickRepairCloak() {
  if (!Bot.active || !Bot.flee || !Bot.fleeing || !Bot.fleeCloak || Bot.fleeCloakUsed
      || !started || player.dead) return;
  if (isPlayerCpuCloaked() || isPlayerCloaked()) {
    Bot.fleeCloakUsed = true;
    return;
  }
  // La fuite continue pendant la recharge. Une seule activation par repli,
  // même si le camouflage est dissipé : éviter des dépenses en boucle.
  if (cloakCd > 0 || player.credits < CPU_CLOAK_COST) return;
  toggleCpuCloak();
  if (isPlayerCpuCloaked()) {
    Bot.fleeCloakUsed = true;
    botLog("Camouflage auto pour réparation (30 000 crédits)");
  }
}

function tickBot(dt) {
  // Seul l'ordre de combat de ce tick peut imposer le NPC au navigateur.
  Bot.combatMoveTargetId = null;
  try { botRecordSightings(dt); } catch {}
  if (!Bot.active) return;
  if (StarJump.channel) return;
  if (!started || player.dead) {
    Bot.cloakPendingMap = null;
    Bot.fleeCloakUsed = false;
    // Compteur de kills/boxes : la cible a disparu pendant la mort.
    Bot.lastNpcId = null;
    Bot.lastNpcKey = null;
    Bot.combatTargetId = null;
    Bot.lastBoxId = null;
    Bot.fleeing = false;
    if (player.dead && started) {
      if (!Bot.wasDead) {
        Bot.wasDead = true;
        Bot.deaths++;
        botRefreshHud();
        if (Bot.maxDeaths > 0 && Bot.deaths >= Bot.maxDeaths) {
          botLog(`Limite de morts atteinte (${Bot.deaths}) — arrêt du bot`);
          botSetActive(false);
          return;
        }
      }
      if (Bot.autoRepair && Bot.active) {
        Bot.repairT += dt;
        if (rules?.mode === "gate") {
          // En Galaxy Gate : seule la sortie vers la base existe.
          Bot.status = "En réparation…";
          Bot.target = "Retour base (gate)";
          if (Bot.repairT >= Math.max(0, Bot.reviveWait)) {
            Bot.repairT = 0;
            try { respawnBaseGate(); botLog("Gate terminée — retour base"); } catch {}
          }
        } else {
        const where = Bot.respawn === "portal" ? "portail" : Bot.respawn === "here" ? "sur place" : "base";
        Bot.status = "En réparation…";
        Bot.target = `Retour ${where}`;
        if (Bot.repairT >= Math.max(0, Bot.reviveWait)) {
          Bot.repairT = 0;
          try {
            if (Bot.respawn === "portal") { respawnNearestPortal(); botLog("Réparation auto au portail"); }
            else if (Bot.respawn === "here") { respawnHere(); botLog("Réparation auto sur place"); }
            else { respawnBase(); botLog("Réparation auto à la base"); }
          } catch {}
        }
        }
      }
    }
    if (Bot.hudT !== 1) { Bot.hudT = 1; botRefreshHud(); }
    return;
  }
  Bot.wasDead = false;
  Bot.grabCd = Math.max(0, (Bot.grabCd || 0) - dt);
  Bot.postKillScanT = Math.max(0, (Bot.postKillScanT || 0) - dt);
  Bot.petFuelT = Math.max(0, (Bot.petFuelT || 0) - dt);
  if (Bot.petEnabled && Bot.petAutoFuel && Bot.petFuelT <= 0) {
    Bot.petFuelT = 5;
    const fuel = Math.max(0, Number(account.user?.pet?.fuel) || 0);
    if (account.user?.pet?.owned === true && fuel <= 20) {
      try {
        const out = buyItem("pet_fuel", 100);
        if (out?.ok) {
          account.user = out.user;
          player.credits = out.user.credits;
          loadAccountUser();
          botApplyPetMode();
        }
      } catch {}
    }
  }

  // Main manuelle récente : le joueur reprend la main, le bot attend.
  // Prioritaire sur tout (fuite et voyage compris).
  if (performance.now() - Bot.manualT < 2500) {
    Bot.status = "Manuel (reprise…)";
    botRefreshHudThrottled(dt);
    return;
  }

  // Flags roquettes auto tenus en continu (restaurés à l'arrêt).
  botApplyRocketFlags();
  if (Bot.skillCloak && Bot.lastNpcKey != null) {
    const killed = enemies.find(enemy => enemy && enemy.hp <= 0 && botNpcHasLockKey(enemy, Bot.lastNpcKey));
    if (killed) botQueueCloakAfterKill(killed);
  }
  if (Bot.cloakPendingMap != null && botTickAutoCloak()) {
    Bot.status = "Camouflage automatique";
    botRefreshHudThrottled(dt);
    return;
  }

  // Compétences auto : IEM si assailli par N+, ISH si coque critique.
  // Vérifiés prêts avant appel (pas de spam de toasts de recharge).
  if ((Bot.skillIem || Bot.skillIsh) && started && !player.dead) {
    let foes = 0;
    try {
      for (const e of enemies) {
        if (npcIsEngagingPlayer(e)) {
          foes++;
          if (foes >= Math.max(1, Bot.iemFoes)) break;
        }
      }
    } catch { foes = 0; }
    if (Bot.skillIem && foes >= Math.max(1, Bot.iemFoes) && pulseCd <= 0 && player.credits >= PULSE_COST) {
      try { usePulse(); botLog(`IEM auto (${foes} assaillants)`); } catch {}
    }
    if (Bot.skillIsh && ishCd <= 0 && player.credits >= ISH_COST) {
      const hpM = Math.max(1, Number(player.hpMax) || 1);
      const hpP = (Number(player.hp) || 0) / hpM * 100;
      if (hpP < Bot.ishPct) {
        try { useIsh(); botLog(`ISH auto (${Math.round(hpP)} % coque)`); } catch {}
      }
    }
  }

  // Quêtes auto (rend + accept au terminal), throttlé en interne.
  if (Bot.questsAccept || Bot.questsClaim) botTickQuests(dt);

  // Seuil de fuite : coque basse → repli dans la ZNA la plus proche, le
  // robot réparateur passif remonte la coque, reprise au seuil + 20 %.
  // Prioritaire sur le voyage et le farm : la survie d'abord.
  const hpMaxSafe = Math.max(1, Number(player.hpMax) || 1);
  const hpPct = (Number(player.hp) || 0) / hpMaxSafe * 100;
  if (Bot.flee && !Bot.fleeing && hpPct < Bot.fleePct) {
    Bot.fleeing = true;
    Bot.fleeCloakUsed = false;
    try { stopAttack(); } catch {}
    try { cancelCollectableTarget(); } catch {}
    try { if (Target.get()) Target.clear(); } catch {}
    botLog(`Coque à ${Math.round(hpPct)} % — fuite vers la zone sûre la plus proche`);
  }
  if (Bot.fleeing) {
    // Reprise explicite (style DarkBot REPAIR_HP_RANGE), plancher = seuil + 5.
    const resumeAt = Math.max(Math.min(100, Bot.fleeResume), Bot.fleePct + 5);
    if (hpPct >= resumeAt) {
      Bot.fleeing = false;
      Bot.fleeCloakUsed = false;
      botLog(`Réparé (${Math.round(hpPct)} %) — reprise du farm`);
    } else {
      Bot.status = "Fuite — réparation";
      Bot.target = `Coque ${Math.round(hpPct)} % (reprise à ${resumeAt} %)`;
      if (attackActive) { try { stopAttack(); } catch {} }
      if (Bot.fleeCloak) botTickRepairCloak();
      botApplyMoveProfile("flee");
      const shelter = botNearestSafeRefuge(player.x, player.y);
      if (shelter) {
        if (attackActive) { try { stopAttack(); } catch {} }
        Bot.target = `${shelter.label} — coque ${Math.round(hpPct)} % (reprise à ${resumeAt} %)`;
        if (Math.hypot(player.x - shelter.x, player.y - shelter.y) <= 35) {
          // Une fois arrive pres du centre, il tient sa position et se repare.
          moveTarget.active = false;
        } else {
          moveTarget.active = true;
          moveTarget.x = clamp(shelter.x, 80, WORLD.w - 80);
          moveTarget.y = clamp(shelter.y, 80, WORLD.h - 80);
        }
      } else if (rules?.mode === "gate") {
        // En Galaxy Gate : pas de portail → kiting : on fuit les menaces en
        // faisant le tour de la map (jamais planté au milieu), tirs coupés,
        // jusqu'à repasser au-dessus du seuil de reprise.
        if (attackActive) { try { stopAttack(); } catch {} }
        try { if (Target.get()) Target.clear(); } catch {}
        let fx = 0, fy = 0;
        for (const e of enemies) {
          if (!e || Number(e.hp) <= 0) continue;
          const ex = player.x - e.x, ey = player.y - e.y;
          const ed = Math.hypot(ex, ey) || 1;
          const w = Math.min(1, 1400 / ed);
          fx += (ex / ed) * w;
          fy += (ey / ed) * w;
        }
        const fl = Math.hypot(fx, fy);
        if (fl > 0.01) {
          // Composante tangentielle pour tourner autour de la map au lieu
          // de se coincer dans un coin (sortie radiation autorisée si plaqué).
          const tx = -fy / fl, ty = fx / fl;
          const rawX = player.x + fx / fl * 900 + tx * 550;
          const rawY = player.y + fy / fl * 900 + ty * 550;
          let nearestD = Infinity;
          try {
            for (const e of enemies) {
              if (!e || Number(e.hp) <= 0) continue;
              const dd = Math.hypot(player.x - e.x, player.y - e.y);
              if (dd < nearestD) nearestD = dd;
            }
          } catch {}
          const tgt = botGateKiteTarget(rawX, rawY, nearestD < 600);
          moveTarget.active = true;
          moveTarget.x = tgt.x;
          moveTarget.y = tgt.y;
        } else {
          moveTarget.active = false;
        }
      } else {
        // Pas de portail sur cette map : on tient position, tirs coupés.
        if (attackActive) { try { stopAttack(); } catch {} }
        moveTarget.active = false;
      }
      botRefreshHudThrottled(dt);
      return;
    }
  }

  // Soute pleine : on raffine d'abord (charge les améliorations), et
  // seulement si vraiment pas moyen on va vendre au comptoir.
  // Jamais en Galaxy Gate (pas de comptoir, pas de sortie auto).
  if (Bot.cargo && !Bot.selling && !player.dead && started && rules?.mode !== "gate") {
    try {
      const c = currentCargo();
      if (c.capacity > 0 && c.used / c.capacity * 100 >= Bot.cargoPct) {
        try { stopAttack(); } catch {}
        try { cancelCollectableTarget(); } catch {}
        try { if (Target.get()) Target.clear(); } catch {}
        const freed = botRefineUpgrades();
        const after = currentCargo();
        if (after.capacity > 0 && after.used / after.capacity * 100 < Bot.cargoPct) {
          botLog(freed > 0 ? `Soute allégée par raffinage (${freed} minerais) — reprise` : "Soute sous le seuil — reprise");
        } else {
          Bot.selling = true;
          botLog(`Soute pleine (${formatInteger(after.used)}/${formatInteger(after.capacity)}) — direction comptoir`);
        }
      }
    } catch {}
  }
  if (Bot.selling) {
    const trade = botNearestTradeModule();
    if (!trade) {
      // Pas de comptoir ici : base la plus proche (X-1 / X-8, préférence
      // respectée), fallback sur l'autre base si besoin.
      const cur = String(window.__CURRENT_MAP_ID__ || "").toLowerCase();
      const next = botPickSellBase(cur).find((m) => m !== cur);
      if (next) {
        if (Bot.travelOverride !== next) botLog(`Direction base ${next.toUpperCase()} (vente)`);
        Bot.travelOverride = next;
      } else {
        Bot.selling = false;
        Bot.travelOverride = null;
        botLog("Soute : aucune base accessible — vente annulée");
      }
    } else {
      Bot.travelOverride = null;
      if (isPlayerNearTradeModule(trade.module)) {
        const gained = botSellOres();
        Bot.selling = false;
        botLog(gained > 0 ? `Vente comptoir : +${formatInteger(gained)} crédits — reprise` : "Soute : rien à vendre — reprise");
      } else {
        Bot.status = "Vente — comptoir";
        Bot.target = `Comptoir (${Math.round(Math.sqrt(trade.d2))}m)`;
        botApplyMoveProfile("explore");
        if (attackActive) { try { stopAttack(); } catch {} }
        moveTarget.active = true;
        moveTarget.x = clamp(trade.pos.x, 80, WORLD.w - 80);
        moveTarget.y = clamp(trade.pos.y, 80, WORLD.h - 80);
        botRefreshHudThrottled(dt);
        return;
      }
    }
  }

  // Voyage inter-maps : 100 % physique, de portail en portail (BFS).
  // AUCUNE téléportation : le vaisseau vole vraiment jusqu'au portail
  // puis saute, étape par étape jusqu'à la carte cible.
  // travelOverride (vente) prime sur la carte cible de l'utilisateur.
  const effRaw = Bot.travelOverride || Bot.targetMap || "";
  const wantMap = String(effRaw).toLowerCase();
  const curMap = String(window.__CURRENT_MAP_ID__ || "1-1").toLowerCase();
  // Module Galaxy Gates : le voyage manuel est désactivé (l'entrée GG gère
  // elle-même le retour base + le saut), sauf override de vente.
  if (wantMap && wantMap !== curMap) {
    Bot.travelCd -= dt;
    Bot.jumpCd -= dt;
    botApplyMoveProfile("travel");
    if (!botPortalIndex) {
      Bot.status = `Voyage → ${String(effRaw).toUpperCase()}`;
      Bot.target = "Cartographie des portails…";
      botRefreshHudThrottled(dt);
      return;
    }
    const route = botFindRoute(curMap, wantMap);
    if (!route) {
      Bot.status = `Voyage → ${String(effRaw).toUpperCase()}`;
      Bot.target = "Aucune route physique";
      if (Bot.travelCd <= 0) {
        Bot.travelCd = 15;
        botLog(`Aucune route physique vers ${String(effRaw).toUpperCase()} — nouvel essai dans 15 s`);
      }
      botRefreshHudThrottled(dt);
      return;
    }
    const nextHop = route[1] || wantMap;
    const portal = (zonePortals || []).find((p) => String(p.toMap || "").toLowerCase() === nextHop);
    if (!portal) {
      Bot.status = `Voyage → ${Bot.targetMap.toUpperCase()}`;
      Bot.target = `Portail vers ${nextHop.toUpperCase()} introuvable ici`;
      botRefreshHudThrottled(dt);
      return;
    }
    const step = route.length > 2 ? ` (via ${nextHop.toUpperCase()})` : "";
    Bot.status = `Voyage → ${String(effRaw).toUpperCase()}${step}`;
    Bot.target = `Portail (${Math.round(Math.hypot(portal.x - player.x, portal.y - player.y))}m)`;
    if (performance.now() - Bot.manualT < 2500) { botRefreshHudThrottled(dt); return; }
    if (attackActive) { try { stopAttack(); } catch {} }
    try { cancelCollectableTarget(); } catch {}
    moveTarget.active = true;
    moveTarget.x = clamp(portal.x, 80, WORLD.w - 80);
    moveTarget.y = clamp(portal.y, 80, WORLD.h - 80);
    if (isPlayerNearPortal(portal) && mapPortalLock <= 0 && !portal.jumping && Bot.jumpCd <= 0) {
      Bot.jumpCd = 3;
      try {
        if (startZonePortalJump(portal)) {
          botLog(route.length > 2 ? `Saut vers ${nextHop.toUpperCase()} (étape)` : `Arrivée sur ${wantMap.toUpperCase()}`);
        } else {
          Bot.target = "Portail : action requise (coût, niveau…)";
        }
      } catch {}
    }
    botRefreshHudThrottled(dt);
    return;
  }

  const wantKill = Bot.mode === "kill" || Bot.mode === "both";
  const wantBox = Bot.mode === "collect" || Bot.mode === "both";
  const foundNpc = wantKill ? botNearestNpc() : null;
  const foundBox = wantBox ? botNearestBox() : null;
  let lockedBox = null;
  if (wantBox && Bot.lastBoxId != null) {
    try {
      lockedBox = collectables.find((box) => box && String(box.id) === String(Bot.lastBoxId)
        && Bot.boxAllow.has(String(box.type))) || null;
    } catch { lockedBox = null; }
  }
  const selectedBox = lockedBox
    ? { box: lockedBox, d2: dist2(player.x, player.y, lockedBox.x, lockedBox.y) }
    : foundBox;

  // Verrouillage auto : sur map on ne change pas de cible tant que
  // l'actuelle n'est pas finie ; en GG on switch librement au plus proche.
  // (Plus d'option : comportement fixé.)
  let lockedNpc = null;
  if (Bot.mode === "kill" || Bot.mode === "both") {
    try {
      const botLocked = Bot.combatTargetId == null ? null
        : enemies.find((enemy) => botNpcHasLockKey(enemy, Bot.combatTargetId));
      // Une cible deja choisie appartient au bot jusqu'a sa mort. Le lock
      // visuel courant ne peut donc pas imposer un autre NPC au milieu d'un
      // groupe (clic, snapshot reseau ou doublon temporaire).
      const cur = Bot.combatTargetId == null ? Target.get() : botLocked;
      if (cur && !cur.isPetTarget && Number(cur.hp) > 0 && enemies.includes(cur)
        && Bot.npcAllow.has(String(cur.type))) {
        // NPC rentré/coincé dans un mur : on casse le lock au lieu de
        // glitcher contre le mur en attendant qu'il ressorte. Ban court
        // pour ne pas le re-locker aussitôt.
        if (botNpcInWall(cur)) {
          try { botNpcBanWall(cur, 8000); } catch {}
          try { if (botTargetIsNpc(cur) && Target.get()) Target.clear(); } catch {}
          try { if (attackActive) stopAttack(); } catch {}
          Bot.combatTargetId = null;
          Bot.lastNpcId = null;
          Bot.lastNpcKey = null;
          lockedNpc = null;
        } else {
          lockedNpc = cur;
          botLockNpc(cur);
        }
      } else {
        Bot.combatTargetId = null;
      }
    } catch { lockedNpc = null; Bot.combatTargetId = null; }
  }

  let pick = null; // { kind: "npc"|"box", ref }
  const gateMode = rules?.mode === "gate";
  if (Bot.module === "galaxy") {
    if (!gateMode) {
      // Hors gate : spinner auto puis entrée auto dans la gate construite.
      try { botTickGalaxySpin(dt); } catch {}
      if (botTickGalaxyEnter(dt)) return;
      Bot.status = "Galaxy Gates";
      Bot.target = Bot.ggSpin ? "Spinner auto… (aucune gate prête)" : "Active le spinner auto (onglet Galaxy)";
      if (attackActive) { try { stopAttack(); } catch {} }
      try { if (Target.get()) Target.clear(); } catch {}
      try { cancelCollectableTarget(); } catch {}
      moveTarget.active = false;
      botRefreshHudThrottled(dt);
      return;
    }
    // Cubikon mort (complétion en cours) : formation + config de fin.
    try { botApplyGalaxyFinishFormation(); } catch {}
    // En gate : toujours le NPC le plus proche, switch immédiat si un plus
    // proche apparaît. Sans risque côté dégâts : le cooldown de tir est
    // conservé au switch (fix global Target.set), seuls les faux tirs
    // visuels suivent la nouvelle cible.
    let cur = null;
    try {
      const t = Target.get();
      if (t && !t.isPetTarget && Number(t.hp) > 0 && enemies.includes(t)) cur = t;
    } catch { cur = null; }
    const nearest = botNearestAnyNpc();
    let found = null;
    if (Bot.ggNearestSwitch === false) {
      found = cur ? { npc: cur } : nearest;
    } else {
      found = nearest;
    }
    if (!found) {
      // Entre les vagues : le bot vole jusqu'au portail "continuer" et saute
      // dedans automatiquement (proximité + startGatePortalJump).
      if (attackActive) { try { stopAttack(); } catch {} }
      try { if (Target.get()) Target.clear(); } catch {}
      // Saut déjà en cours : on attend la vague suivante.
      if (portal.jumping) {
        Bot.status = "Galaxy Gates";
        Bot.target = "Saut vers la vague suivante…";
        moveTarget.active = false;
        botRefreshHudThrottled(dt);
        return;
      }
      if (betweenWaves && portal.active) {
        Bot.status = "Galaxy Gates";
        const d = Math.round(Math.hypot(portal.x - player.x, portal.y - player.y));
        Bot.target = `Portail vague suivante (${d}m)`;
        moveTarget.active = true;
        moveTarget.x = clamp(portal.x, 80, WORLD.w - 80);
        moveTarget.y = clamp(portal.y, 80, WORLD.h - 80);
        if (isPlayerNearPortal(portal)) {
          try { startGatePortalJump(portal, "continue"); } catch {}
        }
        botRefreshHudThrottled(dt);
        return;
      }
      // Vague en cours d'apparition (spawns à venir) : on patiente.
      // Si le Cubikon vient de mourir (complétion en cours), on garde la
      // formation + config de fin jusqu'au renvoi sur la map mère.
      try { botApplyGalaxyFinishFormation(); } catch {}
      Bot.status = "Galaxy Gates";
      Bot.target = "Vague en cours…";
      moveTarget.active = false;
      botRefreshHudThrottled(dt);
      return;
    }
    pick = { kind: "npc", ref: found.npc };
  } else if (Bot.module === "quest") {
    // On ne vise que les cibles réclamées par les quêtes actives.
    const qt = botQuestTargets();
    const qNpc = qt.npcs.size ? botNearestQuestNpc(qt.npcs) : null;
    const qBox = qt.boxes.size ? botNearestQuestBox(qt.boxes) : null;
    if (lockedNpc && (qt.npcs.has("*") || qt.npcs.has(String(lockedNpc.type)))) {
      pick = { kind: "npc", ref: lockedNpc };
    } else if (Bot.priority === "box") {
      pick = qBox ? { kind: "box", ref: qBox.box } : (qNpc ? { kind: "npc", ref: qNpc.npc } : null);
    } else if (Bot.priority === "nearest") {
      if (qNpc && qBox) pick = qNpc.d2 <= qBox.d2 ? { kind: "npc", ref: qNpc.npc } : { kind: "box", ref: qBox.box };
      else if (qNpc) pick = { kind: "npc", ref: qNpc.npc };
      else if (qBox) pick = { kind: "box", ref: qBox.box };
    } else {
      pick = qNpc ? { kind: "npc", ref: qNpc.npc } : (qBox ? { kind: "box", ref: qBox.box } : null);
    }
    if (!pick) Bot.target = "Aucune cible de quête";
  } else if (Bot.mode === "kill") pick = lockedNpc ? { kind: "npc", ref: lockedNpc } : (foundNpc ? { kind: "npc", ref: foundNpc.npc } : null);
  else if (Bot.mode === "collect") pick = selectedBox ? { kind: "box", ref: selectedBox.box } : null;
  else if (Bot.priority === "box") pick = selectedBox
    ? { kind: "box", ref: selectedBox.box }
    : (lockedNpc ? { kind: "npc", ref: lockedNpc } : (foundNpc ? { kind: "npc", ref: foundNpc.npc } : null));
  else if (Bot.priority === "nearest") {
    // "Les deux simultanement" choisit le NPC le plus proche uniquement au
    // debut d'un combat. Un autre NPC qui s'approche ne remplace jamais la
    // cible vivante deja verrouillee.
    const nearestNpc = lockedNpc
      ? { npc: lockedNpc, d2: dist2(player.x, player.y, lockedNpc.x, lockedNpc.y) }
      : botNearestNpcByDistance();
    const simultaneousReach = Math.max(900, botEngageRange() * 1.5);
    const simultaneousBoxReach = Math.max(1800, botEngageRange() * 2.5);
    if (nearestNpc && selectedBox) {
      const boxToNpc = Math.hypot(selectedBox.box.x - nearestNpc.npc.x, selectedBox.box.y - nearestNpc.npc.y);
      const playerToBox = Math.sqrt(selectedBox.d2);
      const continuingBox = lockedBox && String(lockedBox.id) === String(selectedBox.box.id);
      const keepBox = continuingBox
        ? (boxToNpc <= simultaneousReach * 1.6 || playerToBox <= simultaneousBoxReach * 1.25)
        : (boxToNpc <= simultaneousReach || playerToBox <= simultaneousBoxReach);
      if (!keepBox && continuingBox) Bot.lastBoxId = null;
      pick = keepBox ? { kind: "box", ref: selectedBox.box } : { kind: "npc", ref: nearestNpc.npc };
    }
    else if (nearestNpc) pick = { kind: "npc", ref: nearestNpc.npc };
    else if (selectedBox) pick = { kind: "box", ref: selectedBox.box };
  } else {
    // NPC d'abord (défaut) : le NPC le plus proche gagne, sinon la box.
    pick = lockedNpc ? { kind: "npc", ref: lockedNpc } : (foundNpc ? { kind: "npc", ref: foundNpc.npc } : (foundBox ? { kind: "box", ref: foundBox.box } : null));
  }

  // Après un kill, les NPC cochés autour du vaisseau sont prioritaires sur
  // toute box ou patrouille. La fenêtre couvre également un spawn/snapshot
  // qui arriverait juste après la disparition de la cible précédente.
  const previousNpcDied = Bot.lastNpcKey != null
    && !enemies.some((enemy) => enemy && botNpcHasLockKey(enemy, Bot.lastNpcKey) && Number(enemy.hp) > 0);
  if (lockedNpc) Bot.postKillScanT = 0;
  else if (previousNpcDied && Bot.mode !== "collect") Bot.postKillScanT = 1.5;
  if (!lockedNpc && Bot.postKillScanT > 0 && Bot.mode !== "collect" && Bot.priority === "npc") {
    const nearbyNpc = botNearestNpcInRange(Math.max(2200, (Number(playerRange) || 700) * 3));
    if (nearbyNpc) pick = { kind: "npc", ref: nearbyNpc };
    else if (pick?.kind === "box") pick = null;
  }

  // Simultané : le pick donne la PRIORITÉ de mouvement, mais en mode mixte
  // les deux tâches tournent ensemble (la branche combat ramasse les box au
  // passage, la branche collecte lock et tire dès que ça porte).

  // Compteurs : cible suivie qui a disparu = kill / collecte réussie.
  if (Bot.lastNpcKey != null && (!foundNpc || !botNpcHasLockKey(foundNpc.npc, Bot.lastNpcKey))) {
    const stillAlive = enemies.some((e) => e && botNpcHasLockKey(e, Bot.lastNpcKey) && Number(e.hp) > 0);
    if (!stillAlive) {
      Bot.kills++;
      botSaveConfig();
      const kc = document.getElementById("botKillCount");
      if (kc) kc.textContent = String(Bot.kills);
      Bot.lastNpcId = null;
      Bot.lastNpcKey = null;
      Bot.combatTargetId = null;
    }
  }
  if (Bot.lastBoxId != null) {
    const stillThere = collectables.some((c) => c && String(c.id) === String(Bot.lastBoxId));
    if (!stillThere) {
      Bot.boxes++;
      botSaveConfig();
      const bc = document.getElementById("botBoxCount");
      if (bc) bc.textContent = String(Bot.boxes);
      Bot.grabCd = 4;
      Bot.lastBoxId = null;
    }
  }

  if (!pick) {
    // Patrouille : waypoint (on reste dessus jusqu'à l'atteindre si configuré,
    // style DarkBot, avec sécurité anti-blocage à 30 s).
    // Fin d'engagement : on oublie la munition speciale en cours.
    try { botClearSpecialAmmo(); } catch {}
    botApplyMoveProfile("explore");
    const blTarget = botBlacklightSearch(dt);
    Bot.roamT -= dt;
    if (blTarget) {
      botOrderMove(blTarget.x, blTarget.y, "search-bl");
    } else if (Bot.roamT <= 0 || !moveTarget.active) {
      Bot.roamT = 6;
      Bot.roamX = 120 + Math.random() * Math.max(240, WORLD.w - 240);
      Bot.roamY = 120 + Math.random() * Math.max(240, WORLD.h - 240);
      moveTarget.active = true;
      moveTarget.x = clamp(Bot.roamX, 80, WORLD.w - 80);
      moveTarget.y = clamp(Bot.roamY, 80, WORLD.h - 80);
    }
    if (attackActive) {
      // Patrouille = aucun NPC : on coupe un tir éventuel sur cible périmée.
      let curOk = false;
      try {
        const cur = Target.get();
        curOk = !!cur && !cur.isPetTarget && Number(cur.hp) > 0 && enemies.includes(cur);
      } catch { curOk = false; }
      if (!curOk) {
        try { stopAttack(); } catch {}
        try { if (Target.get()) Target.clear(); } catch {}
        Bot.lastNpcId = null;
        Bot.lastNpcKey = null;
        Bot.combatTargetId = null;
      }
    }
    Bot.status = Bot.mode === "collect" ? "Collecte — patrouille" : Bot.mode === "kill" ? "Chasse — patrouille" : "Farm — patrouille";
    Bot.target = "Recherche de cible…";
    if (blTarget) Bot.target = `Recherche : ${NPC_TYPES[blTarget.type]?.name || blTarget.type}`;
    if (Bot.module === "quest") {
      Bot.status = "Quêtes — patrouille";
      Bot.target = "Aucune cible (accepte des quêtes)";
    }
    botRefreshHudThrottled(dt);
    return;
  }

  if (pick.kind === "npc") {
    const npc = pick.ref;
    botLockNpc(npc);
    const d = Math.hypot(npc.x - player.x, npc.y - player.y);
    const fullD = botCombatDistance(npc);
    if (Bot.rangeRecoveryId !== npc.id) {
      Bot.rangeRecoveryId = npc.id;
      Bot.rangeRecovering = d < fullD - 12;
      Bot.closeId = null;
      Bot.chaseId = null;
      Bot.aggroId = null;
    }
    // NPC qui ne nous chasse pas (passif) : kiting resserré à 250 m pour
    // le finir au lieu de glitcher à strafer au max. Dès qu'il riposte,
    // retour au max range pour le reste du combat (anti yoyo). Jamais en GG.
    const isGgCombat0 = Bot.module === "galaxy" && rules?.mode === "gate";
    let engaging = true;
    try { engaging = typeof npcIsEngagingPlayer === "function" ? npcIsEngagingPlayer(npc) === true : true; } catch { engaging = true; }
    if (engaging) Bot.aggroId = npc.id;
    const targetCanShoot = (Number(npc.shootRange) || Number(NPC_TYPES[npc.type]?.shootRange) || 0) > 0;
    const passive = !targetCanShoot && !isGgCombat0 && engaging !== true && Bot.aggroId !== npc.id && Bot.chaseId !== npc.id;
    const standD = passive ? Math.min(fullD, 250) : fullD;
    if (d < standD - 12) Bot.rangeRecovering = true;
    else if (d >= standD + 20) Bot.rangeRecovering = false;
    const mustRetreat = Bot.rangeRecovering === true;
    // Quand la distance est perdue, la configuration et la formation de fuite
    // passent avant celles d'attaque afin d'utiliser la meilleure vitesse
    // disponible. Une fois le rayon recupere, l'equipement d'attaque revient.
    const npcForm = Bot.npcForm[String(npc.type)] || "";
    const npcCfg = Bot.npcCfg[String(npc.type)] || "";
    botApplyFormation(npcForm);
    botApplyConfig(npcCfg);
    const npcName = String((NPC_TYPES[npc.type]?.name || npc.type || "NPC")).replace(/^-=\[?\s*|\s*\]?=-$/g, "").trim() || "NPC";
    try { if (!botTargetIsNpc(npc)) Target.set(npc); } catch {}
    // Le tir continue même si on se décale vers une box (simultané) : jamais
    // de cancelCollectableTarget ici, et pas de reset de lastBoxId (compteur).
    botApplyNpcAmmo(npc);
    // Tir UNIQUEMENT à portée (jamais de lock + tir à l'autre bout de la
    // carte) : hors portée on approche en silence, à portée max on engage.
    // On ne coupe que 20 m au-delà (epsilon anti on/off, pas un réglage).
    const engageMax = botEngageRange();
    if (!attackActive && d <= botEngageStartRange()) {
      try { startAttack(); } catch {}
    } else if (attackActive && d > engageMax + 20) {
      try { stopAttack(); } catch {}
    }
    // Munitions speciales auto (SAB bouclier / X6 burst).
    try { botAutoSpecialAmmo(npc, d, engageMax); } catch {}
    // Une cible NPC engagee garde la priorite absolue sur le mouvement.
    // La collecte reprendra apres le combat : aucune box ne peut maintenant
    // detourner le vaisseau du rayon de combat demande.
    let grab = null;
    try { grab = botGrabBoxForFight(npc, standD); } catch { grab = null; }
    if (!grab) { try { if (collectableTargetId != null) cancelCollectableTarget(); } catch {} }
    if (grab && d > engageMax * 1.1) {
      try { if (collectableTargetId === grab.box.id) cancelCollectableTarget(); } catch {}
      Bot.lastBoxId = null;
      grab = null;
    }
    if (grab) {
      if (collectableTargetId !== grab.box.id) {
        collectableTargetId = grab.box.id;
        grab.box.armed = true;
        grab.box.collectT = 0;
      }
      Bot.lastBoxId = grab.box.id;
      Bot.status = Bot.mode === "both" ? "Farm — combat + collecte" : "Chasse — collecte";
      Bot.target = `${npcName} (${Math.round(d)}m) + ${String(COLLECTABLE_TYPES[grab.box.type]?.name || grab.box.type)} (${Math.round(Math.sqrt(grab.d2))}m)`;
      moveTarget.active = true;
      moveTarget.x = clamp(grab.box.x + (COLLECTABLE_PICKUP.offsetX || 0), 80, WORLD.w - 80);
      moveTarget.y = clamp(grab.box.y + (COLLECTABLE_PICKUP.offsetY || 0), 80, WORLD.h - 80);
      botRefreshHudThrottled(dt);
      return;
    }
    Bot.status = Bot.mode === "both" ? "Farm — combat" : "Chasse — combat";
    Bot.target = `${npcName} — ${Math.round(d)}m / cible ${Math.round(standD)}m`;
    // Kiting (jamais immobile sous les tirs) : on garde la distance de tir
    // à la cible, on repousse les autres NPC proches et on strafe.
    const isGgCombat = Bot.module === "galaxy" && rules?.mode === "gate";
    // Tout au max range laser (standD = playerRange live). Kiting partout.
    // POURSUITE : le NPC se sauve en plein combat (on était au contact et
    // il a filé au-delà de +150 m, ou il s'éloigne vite au-delà de +60 m)
    // → kiting resserré à 120 m pour le coller et le finir.
    let chasing = false;
    if (!isGgCombat && !targetCanShoot) {
      if (Bot.closeId !== npc.id && d <= standD + 60) Bot.closeId = npc.id;
      let fleeing = false;
      if (Bot.closeId === npc.id && d > 0.01) {
        if (d > standD + 150) fleeing = true;
        else if (d > standD + 60) {
          try {
            const rdx = npc.x - player.x, rdy = npc.y - player.y;
            const rvx = (Number(npc.vx) || 0) - (Number(player.vx) || 0);
            const rvy = (Number(npc.vy) || 0) - (Number(player.vy) || 0);
            if ((rvx * rdx + rvy * rdy) / d > 150) fleeing = true;
          } catch {}
        }
      }
      if (fleeing) Bot.chaseId = npc.id;
      else if (Bot.chaseId === npc.id && d <= 120) Bot.chaseId = null;
      chasing = Bot.chaseId === npc.id;
    }
    // Kiting partout : poursuite resserrée si fuite (le kite fait l'approche
    // tout seul hors portée, puis colle à 120 m en tirant), sinon kiting
    // normal. (Première attaque incluse : même approche.)
    if (chasing) {
      Bot.status = Bot.mode === "both" ? "Farm — poursuite" : "Chasse — poursuite";
      Bot.target = `${npcName} en fuite (${Math.round(d)}m) — kiting resserré`;
      botKiteCombatMove(npc, d, 120, dt);
    } else {
      botKiteCombatMove(npc, d, standD, dt);
    }
  } else {
    const box = pick.ref;
    Bot.lastBoxId = box.id;
    botApplyFormation(Bot.formCollect || Bot.formMove);
    botApplyConfig(Bot.cfgCollect || Bot.cfgFly);
    const d = Math.hypot(box.x - player.x, box.y - player.y);
    const boxName = String(COLLECTABLE_TYPES[box.type]?.name || box.type || "Box");
    // Simultané : on lock et on tire dès que ça porte, SANS quitter la box.
    // Le vaisseau continue vers la collecte pendant que les lasers partent.
    const foe = botConcurrentNpc(botEngageRange(), lockedNpc);
    if (foe) botEngageNpc(foe);
    else if (!lockedNpc) {
      // Plus rien à portée : on décroche proprement (cible morte ou partie),
      // sinon on garde l'attaque (le tick de tir gère déjà la portée).
      if (attackActive) { try { stopAttack(); } catch {} }
      try { if (Target.get()) Target.clear(); } catch {}
      Bot.combatTargetId = null;
      Bot.lastNpcId = null;
      Bot.lastNpcKey = null;
      botClearSpecialAmmo();
    } else if (attackActive) {
      // Hors portee pendant le trajet : on coupe seulement le tir. Le NPC et
      // la box restent tous les deux verrouilles, sans bascule entre eux.
      try { stopAttack(); } catch {}
    }
    const shownFoe = foe || lockedNpc;
    if (shownFoe) {
      const foeDistance = Math.hypot(shownFoe.x - player.x, shownFoe.y - player.y);
      const fd = Math.round(foeDistance);
      const foeName = String((NPC_TYPES[shownFoe.type]?.name || shownFoe.type || "NPC")).replace(/^-=\[?\s*|\s*\]?=-$/g, "").trim() || "NPC";
      Bot.status = Bot.mode === "both" ? "Farm — collecte + combat" : "Collecte + combat";
      Bot.target = `${boxName} (${Math.round(d)}m) + ${foeName} (${fd}m)`;
      botLockNpc(shownFoe);
    } else {
      Bot.status = Bot.mode === "both" ? "Farm — collecte" : "Collecte";
      Bot.target = `${boxName} (${Math.round(d)}m)`;
    }
    try {
      if (collectableTargetId !== box.id) selectCollectable(box);
    } catch {
      moveTarget.active = true;
      moveTarget.x = clamp(box.x, 80, WORLD.w - 80);
      moveTarget.y = clamp(box.y, 80, WORLD.h - 80);
    }
  }
  botRefreshHudThrottled(dt);
}

function botRefreshHudThrottled(dt) {
  Bot.hudT += dt;
  if (Bot.hudT >= 0.25) { Bot.hudT = 0; botRefreshHud(); }
}

// Overlays du bot (bot actif uniquement) : traits vers les NPC cochés,
// cercle de portée autour du vaisseau, portée de chaque NPC, zones de
// non-agression (portails sûrs, base, modules sûrs).
function drawBotOverlays(ox, oy) {
  if (!Bot.active || !Bot.overlay) return;
  if (!started || player.dead) return;
  const px = player.x + ox;
  const py = player.y + oy;
  const inView = (x, y, m) => x > -m && x < innerWidth + m && y > -m && y < innerHeight + m;
  ctx.save();
  ctx.lineWidth = 1.5;
  // 1. Traits vaisseau -> NPC sélectionnés (cochés, vivants, 60 proches).
  // 3. Rayon d'attaque de chaque NPC (40 proches).
  try {
    const cands = [];
    for (const e of enemies) {
      if (!e || Number(e.hp) <= 0 || e.isPetTarget) continue;
      if (!Bot.npcAllow.has(String(e.type))) continue;
      cands.push(e);
    }
    cands.sort((a, b) => dist2(player.x, player.y, a.x, a.y) - dist2(player.x, player.y, b.x, b.y));
    ctx.strokeStyle = "rgba(0,217,255,0.45)";
    ctx.beginPath();
    for (const e of cands.slice(0, 60)) {
      const sx = e.x + ox;
      const sy = e.y + oy;
      if (!inView(sx, sy, 50)) continue;
      ctx.moveTo(px, py);
      ctx.lineTo(sx, sy);
    }
    ctx.stroke();
    ctx.strokeStyle = "rgba(255,70,70,0.5)";
    for (const e of cands.slice(0, 40)) {
      const r = Number(NPC_TYPES[e.type]?.shootRange) || 0;
      if (!(r > 0)) continue;
      const sx = e.x + ox;
      const sy = e.y + oy;
      if (!inView(sx, sy, r)) continue;
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, TAU);
      ctx.stroke();
    }
  } catch {}
  // 2. Cercle de portée d'attaque autour du vaisseau (+ engagement si réglé).
  try {
    ctx.strokeStyle = "rgba(110,255,150,0.65)";
    ctx.beginPath();
    ctx.arc(px, py, playerRange, 0, TAU);
    ctx.stroke();
  } catch {}
  // 4. Zones de non-agression : portails sûrs, base, modules sûrs.
  try {
    ctx.strokeStyle = "rgba(150,130,255,0.55)";
    for (const p of getInteractivePortals()) {
      try { if (!portalProvidesSafety(p)) continue; } catch { continue; }
      const rr = DEFAULT_PORTAL_RADIUS + SAFE_ZONE_MARGIN;
      const sx = p.x + ox;
      const sy = p.y + oy;
      if (!inView(sx, sy, rr)) continue;
      ctx.beginPath();
      ctx.arc(sx, sy, rr, 0, TAU);
      ctx.stroke();
    }
    try {
      if (typeof baseProvidesSafety === "function" && baseProvidesSafety() && zoneSafe?.zone?.kind === "circle") {
        const z = zoneSafe.zone;
        const rr = (Number(z.r) || 0) + SAFE_ZONE_MARGIN;
        const sx = z.x + ox;
        const sy = z.y + oy;
        if (inView(sx, sy, rr)) {
          ctx.beginPath();
          ctx.arc(sx, sy, rr, 0, TAU);
          ctx.stroke();
        }
      }
    } catch {}
    ctx.setLineDash([6, 6]);
    for (const m of zoneSafe?.modules || []) {
      const rr = Number(m?.safeRadius) || 0;
      if (!(rr > 0) || !canUseStation(m)) continue;
      const sx = m.x + ox;
      const sy = m.y + oy;
      if (!inView(sx, sy, rr)) continue;
      ctx.beginPath();
      ctx.arc(sx, sy, rr, 0, TAU);
      ctx.stroke();
    }
    ctx.setLineDash([]);
  } catch {}
  ctx.restore();
}

registerHudWindows();

// ============================================================
// ✅ Fenêtre P.E.T en jeu : play/stop, mode passif/combat, barres
// HP / bouclier / XP / fuel (réservoir 50 000, consommé en jeu).
// ============================================================
// Somme des % d'un protocole équipé sur le fit actif (chaleur ignorée :
// supprimée du jeu). Ex : "cargo", "radar", "salvage", "shield",
// "damage", "aim", "evasion", "hp", "alien", "eco".
function getPetProtocolPct(pet, user, key) {
  const want = String(key || "").toLowerCase();
  if (!want || want === "heat") return 0;
  const hangar = (user?.hangars || []).find((h) => h?.active) || null;
  const hid = hangar ? String(hangar.id) : null;
  const cfg = String(Number(hangar?.activeConfig) === 2 ? 2 : 1);
  const fit = hid ? getPetFit(pet, hid, cfg) : null;
  let total = 0;
  for (const itemId of fit?.protocols || []) {
    const item = itemId ? findCatalogItem(itemId) : null;
    const k = String(item?.petProtocol?.key || "").toLowerCase();
    if (!k || k === "heat" || k !== want) continue;
    total += Number(item.petProtocol.pct) || 0;
  }
  return Math.max(0, total);
}
function petFuelEcoMult(pet, user) {
  const eco = getPetProtocolPct(pet, user, "eco");
  return Math.max(0, 1 - eco / 100);
}
// Portée d'un gear avec le protocole radar (+X % sur G-AL / G-AR / G-EL).
function getPetGearRangeWithRadar(key, level, pet, user) {
  const base = getPetGearRange(key, level);
  if (!(base > 0)) return 0;
  const radar = getPetProtocolPct(pet, user, "radar");
  return radar > 0 ? base * (1 + radar / 100) : base;
}
function petShieldMaxForHud(pet, user) {
  return getPetVitalLimits(pet, user).shMax;
}

function wirePetWindow() {
  ui.petPlayBtn?.addEventListener("click", () => {
    const pet = account.user?.pet?.owned === true ? account.user.pet : null;
    if (!pet) return showToast("P.E.T non possédé.", 1.5);
    // REX détruit : la clé répare (10 000 crédits, coque pleine).
    if (!(Number(pet.hp) > 0)) {
      // Flush memoire -> store : sinon la reparation lit un store perime
      // (kill recent pas encore sauvegarde) et repond "REX intact." a tort.
      try { if (account.user) saveProgressNow(); } catch {}
      const out = repairPet();
      if (!out?.ok) return showToast(out?.error || "Impossible.", 1.5);
      account.user = out.user;
      player.credits = out.user.credits;
      setHudText(ui.shopCredits, formatInteger(player.credits));
      loadAccountUser();
      markProgressDirty();
      window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
      return showToast("REX réparé (coque 10 %, bouclier 0).", 1.8);
    }
    // Panne sèche : la goutte achète +100 essence (10 000 crédits débités),
    // sans activer le REX — le bouton repasse en play, à toi de l'allumer.
    if (!(Math.max(0, Math.floor(Number(pet.fuel) || 0)) > 0)) {
      const out = buyItem("pet_fuel", 100);
      if (!out?.ok) return showToast(out?.error || "Impossible.", 1.5);
      account.user = out.user;
      player.credits = out.user.credits;
      setHudText(ui.shopCredits, formatInteger(player.credits));
      loadAccountUser();
      markProgressDirty();
      window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
      return showToast(`+${formatInteger(out.quantity)} essence (${formatInteger(out.totalPrice)} crédits) — appuie sur play.`, 2);
    }
    const out = setPetActive(!pet.active);
    if (!out?.ok) return showToast(out?.error || "Impossible.", 1.5);
    loadAccountUser();
    showToast(out.active ? "P.E.T activé" : "P.E.T désactivé", 1.2);
  });
  // Achat rapide d'essence : bouton permanent (même réservoir non vide).
  ui.petFuelBuyBtn?.addEventListener("click", () => {
    const pet = account.user?.pet?.owned === true ? account.user.pet : null;
    if (!pet) return showToast("P.E.T non possédé.", 1.5);
    const out = buyItem("pet_fuel", 100);
    if (!out?.ok) return showToast(out?.error || "Impossible.", 1.5);
    account.user = out.user;
    player.credits = out.user.credits;
    setHudText(ui.shopCredits, formatInteger(player.credits));
    loadAccountUser();
    markProgressDirty();
    window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
    showToast(`+${formatInteger(out.quantity)} essence (${formatInteger(out.totalPrice)} crédits).`, 2);
  });
  // Menus custom P.E.T : toggle à volonté, jamais fermés au clic ailleurs.
  ui.petModeBtn?.addEventListener("click", () => {
    if (ui.petModeBtn.disabled) return;
    ui.petModeList.hidden = !ui.petModeList.hidden;
    placePetDropdown(ui.petModeBtn, ui.petModeList);
  });
  ui.petNpcBtn?.addEventListener("click", () => {
    if (ui.petNpcBtn.disabled) return;
    ui.petNpcList.hidden = !ui.petNpcList.hidden;
    placePetDropdown(ui.petNpcBtn, ui.petNpcList);
  });
  ui.petModeList?.addEventListener("click", (event) => {
    const btn = event.target.closest("button[data-value]");
    if (!btn || btn.disabled) return;
    ui.petModeList.hidden = true;
    applyPetModeValue(String(btn.dataset.value || "passive"));
  });
  ui.petNpcList?.addEventListener("click", (event) => {
    const btn = event.target.closest("button[data-value]");
    if (!btn || btn.disabled) return;
    ui.petNpcList.hidden = true;
    petLocator.manualType = btn.dataset.value || null;
    petLocator.enemyId = null;
  });
}

// Menus custom P.E.T : flottants (position fixe), recalculés pour suivre
// la fenêtre (drag) et s'ouvrir vers le haut si le bas manque.
function placePetDropdown(btn, list) {
  if (!btn || !list || list.hidden) return;
  const r = btn.getBoundingClientRect();
  const h = list.offsetHeight || 200;
  let top = r.bottom + 4;
  if (top + h > window.innerHeight) top = Math.max(4, r.top - 4 - h);
  list.style.left = `${Math.max(4, Math.min(r.left, window.innerWidth - 160))}px`;
  list.style.top = `${top}px`;
  list.style.width = `${Math.max(120, r.width)}px`;
}

// Libellé court du menu Mode : sans les codes G- ("G-AL3 · Auto-Loot" → "Auto-Loot").
function shortGearLabel(label) {
  const parts = String(label || "").split("·");
  return (parts.length > 1 ? parts[parts.length - 1] : parts[0] || "").trim() || String(label || "");
}

// Un seul comportement à la fois : Passif, Mode combat ou un gear équipé.
function applyPetModeValue(v) {
    const pet = account.user?.pet?.owned === true ? account.user.pet : null;
    if (!pet) return showToast("P.E.T non possédé.", 1.5);
    v = String(v || "passive");
    // Kamikaze en cours : course verrouillée, rien ne peut l'arrêter.
    if (kkRunActive()) {
      loadAccountUser();
      return showToast("Kamikaze en cours — REX verrouillé.", 1.5);
    }
    // Un seul comportement à la fois : Passif, Mode combat ou un gear équipé.
    if (v.startsWith("gear:")) {
      const key = v.slice("gear:".length).toLowerCase();
      // Sans carburant, aucun gear ne peut s'activer.
      if (!(Math.max(0, Math.floor(Number(account.user?.pet?.fuel) || 0)) > 0)) {
        loadAccountUser();
        return showToast("Plus de carburant — achète de l'essence P.E.T.", 1.8);
      }
      // Changer de comportement ferme le Trader (→ cooldown) et coupe lien/bouée.
      if (traWindowActive()) endTraSession();
      if (hplLinkActive() && key !== "hpl") endHplLink("gear");
      if (buoySessionActive() && key !== petBuoy.key) endBuoySession("gear");
      if (key === "tra") {
        const left = traCooldownLeftSec();
        if (left > 0) {
          showToast(`Cargo Trader prêt dans ${Math.ceil(left)} s`, 1.8);
          loadAccountUser();
          return;
        }
        // Mémorise le comportement courant pour y revenir après la session.
        petTrader.prevMode = normalizePetMode(account.user?.pet?.mode);
        const prevGear = String(account.user?.pet?.activeGear || "").toLowerCase() || null;
        petTrader.prevGear = prevGear && prevGear !== "tra" ? prevGear : null;
        const outMode = setPetMode("passive");
        if (!outMode?.ok) return showToast(outMode?.error || "Impossible.", 1.5);
        const out = setPetActiveGear("tra");
        if (!out?.ok) return showToast(out?.error || "Impossible.", 1.5);
        const lvl = Math.floor(Number(petGearLevels().tra) || 0);
        if (!(lvl > 0)) {
          setPetActiveGear(null);
          loadAccountUser();
          return showToast("Gear déséquipé.", 1.5);
        }
        petTrader.level = lvl;
        petTrader.until = performance.now() / 1000 + PET_GEAR_TRADE_WINDOW_SEC;
        if (!openTraTradeWindow()) {
          petTrader.until = 0;
          petTrader.level = 0;
          setPetActiveGear(null);
          loadAccountUser();
          return;
        }
        petLocator.manualType = null;
        petLocator.enemyId = null;
        petLocator.needsPick = true;
        loadAccountUser();
        showToast(`Cargo Trader : commerce ouvert 10 s (+${getPetTradeBonusPct(lvl)} %)`, 2);
        return;
      }
      if (key === "fs") {
        const left = fsCooldownLeftSec();
        if (left > 0) {
          showToast(`Flamme sacrificielle prête dans ${Math.ceil(left)} s`, 1.8);
          loadAccountUser();
          return;
        }
        triggerSacrificeFlame();
        return;
      }
      if (key === "kk") {
        const left = kkCooldownLeftSec();
        if (left > 0) {
          showToast(`Kamikaze prêt dans ${Math.ceil(left)} s`, 1.8);
          loadAccountUser();
          return;
        }
        triggerPetKamikaze();
        return;
      }
      if (key === "hpl") {
        if (hplLinkActive()) {
          showToast("Lien HP déjà actif.", 1.2);
          loadAccountUser();
          return;
        }
        const left = hplCooldownLeftSec();
        if (left > 0) {
          showToast(`Lien HP prêt dans ${Math.ceil(left)} s`, 1.8);
          loadAccountUser();
          return;
        }
        startHplLink();
        return;
      }
      if (key === "bc" || key === "bh") {
        if (buoySessionActive() && petBuoy.key === key) {
          showToast("Bouée déjà active.", 1.2);
          loadAccountUser();
          return;
        }
        const left = buoyCooldownLeftSec(key);
        if (left > 0) {
          showToast(`Bouée prête dans ${Math.ceil(left)} s`, 1.8);
          loadAccountUser();
          return;
        }
        startBuoySession(key);
        return;
      }
      // Les helpers de compte relisent le store : pousse d'abord les PV et le
      // bouclier live pour qu'un changement de gear ne restaure pas une valeur
      // ancienne (souvent 0 juste apres un combat).
      try { if (account.user) saveProgressNow(); } catch {}
      const outMode = setPetMode("passive");
      if (!outMode?.ok) return showToast(outMode?.error || "Impossible.", 1.5);
      const out = setPetActiveGear(key);
      if (!out?.ok) return showToast(out?.error || "Impossible.", 1.5);
      petLocator.manualType = null;
      petLocator.enemyId = null;
      petLocator.needsPick = true;
      loadAccountUser();
      const label = shortGearLabel(petEquippedGearOptions().find((e) => e.key === key)?.label) || key.toUpperCase();
      showToast(`P.E.T : ${label} actif`, 1.2);
      return;
    }
    // Changer de comportement ferme le Trader (→ cooldown) et coupe lien/bouée.
    if (traWindowActive()) endTraSession();
    if (hplLinkActive()) endHplLink("gear");
    if (buoySessionActive()) endBuoySession("gear");
    try { if (account.user) saveProgressNow(); } catch {}
    const out = setPetMode(v);
    if (!out?.ok) {
      showToast(out?.error || "Impossible.", 1.5);
      return;
    }
    setPetActiveGear(null);
    petLocator.manualType = null;
    petLocator.enemyId = null;
    petLocator.needsPick = true;
    loadAccountUser();
    showToast(out.mode === "combat" ? "P.E.T : mode combat" : "P.E.T : passif", 1.2);
}

function updatePetHud() {
  const pet = account.user?.pet?.owned === true ? account.user.pet : null;
  const has = !!pet;
  if (ui.petNoPet) ui.petNoPet.hidden = has;
  setHudDisabled(ui.petPlayBtn, !has);
  if (ui.petModeBtn) ui.petModeBtn.disabled = !has;

  const level = has ? getPetLevel(pet.exp) : 0;
  const exp = has ? Math.max(0, Number(pet.exp) || 0) : 0;
  const hpMax = has ? petMaxHpWithHeat(pet) : 0;
  const hp = has ? Math.max(0, Math.min(hpMax, Math.floor(Number(pet.hp)))) : 0;
  const shMax = has ? petShieldMaxForHud(pet, account.user) : 0;
  const sh = has
    ? (pet.sh != null && Number.isFinite(Number(pet.sh)) ? Math.max(0, Math.min(shMax, Math.floor(Number(pet.sh)))) : shMax)
    : 0;
  const next = has ? getPetNextLevelXp(level) : 1;
  const prev = has ? getPetLevelXp(level) : 0;
  // Progression infinie : plus de plafond au niveau 20.
  const xpPct = Math.max(0, Math.min(100, ((exp - prev) / Math.max(1, next - prev)) * 100));
  if (level > 15) setHudText(ui.petXpTxt, `${formatInteger(Math.floor(exp))} - ${level}`);
  else setHudText(ui.petXpTxt, `${formatInteger(Math.floor(exp))} / ${formatInteger(next)} - ${level}`);
  setHudWidth(ui.petXpBar, `${xpPct}%`);
  if (has) setHudText(ui.petNameTxt, String(pet.pseudo || "REX"));
  setHudText(ui.petHpTxt, `${formatInteger(hp)} / ${formatInteger(hpMax)}`);
  setHudWidth(ui.petHpBar, `${hpMax > 0 ? (hp / hpMax) * 100 : 0}%`);
  setHudText(ui.petShTxt, `${formatInteger(sh)} / ${formatInteger(shMax)}`);
  setHudWidth(ui.petShBar, `${shMax > 0 ? (sh / shMax) * 100 : 0}%`);
  if (ui.petShBar?.parentElement) setHudDisplay(ui.petShBar.closest?.(".petMeter") || ui.petShBar.parentElement, shMax > 0 ? "" : "none");
  const fuelMax = has ? Math.max(1, Math.floor(Number(pet.fuelMax) || PET_FUEL_MAX)) : PET_FUEL_MAX;
  const fuel = has ? Math.max(0, Math.min(fuelMax, Math.floor(Number(pet.fuel) || 0))) : 0;
  setHudText(ui.petFuelTxt, `${formatInteger(fuel)} / ${formatInteger(fuelMax)}`);
  setHudWidth(ui.petFuelBar, `${fuelMax > 0 ? (fuel / fuelMax) * 100 : 0}%`);
  // Achat rapide permanent : visible dès que le P.E.T est possédé,
  // désactivé seulement si le réservoir est déjà plein.
  if (ui.petFuelBuyBtn) {
    setHudDisplay(ui.petFuelBuyBtn, has ? "" : "none");
    setHudDisabled(ui.petFuelBuyBtn, !has || fuel >= fuelMax);
    setHudAttr(ui.petFuelBuyBtn, "title", fuel >= fuelMax
      ? "Réservoir plein"
      : "+100 essence — 10 000 crédits");
  }

  if (ui.petPlayBtn) {
    const destroyed = has && !(Number(pet.hp) > 0);
    // À sec = éteint : jamais l'icône pause avec un réservoir vide,
    // même pendant la frame où la désactivation se propage.
    const outOfFuel = has && !(Math.max(0, Math.floor(Number(pet.fuel) || 0)) > 0);
    const shownActive = pet?.active === true && !outOfFuel && !destroyed;
    // ✅ l'icône ne change que d'état (play / pause / clé) : on ne touche au
    // DOM que sur changement. Avant, la comparaison innerHTML ne matchait
    // jamais (sérialisation navigateur) donc le SVG était recréé à chaque
    // frame et le clic tombait sur un nÅ“ud détruit entre mousedown/mouseup.
    const iconKey = !has ? "none" : destroyed ? "wrench" : outOfFuel ? "fuel" : shownActive ? "pause" : "play";
    if (iconKey !== lastPetPlaySig) {
      lastPetPlaySig = iconKey;
      const label = iconKey === "wrench"
        ? '<svg viewBox="0 0 16 16" width="14" height="14"><path d="M11.5 1a3.5 3.5 0 0 0-4.6 4.6L1 11.5V15h3.5l5.9-5.9A3.5 3.5 0 0 0 15 4.5l-2.3 2.3-2.4-.6-.6-2.4L11.5 1z" fill="#eaffff"/></svg>'
        : iconKey === "fuel"
          ? '<svg viewBox="0 0 16 16" width="14" height="14"><path d="M8 1.2C8 1.2 2.6 8.2 2.6 11.3a5.4 5.4 0 0 0 10.8 0C13.4 8.2 8 1.2 8 1.2z" fill="#7cf0ff"/></svg>'
          : iconKey === "pause"
          ? '<svg viewBox="0 0 16 16" width="14" height="14"><rect x="3" y="2" width="4" height="12" rx="1" fill="#eaffff"/><rect x="9" y="2" width="4" height="12" rx="1" fill="#eaffff"/></svg>'
          : '<svg viewBox="0 0 16 16" width="14" height="14"><path d="M4 2 L13 8 L4 14 Z" fill="#eaffff"/></svg>';
      ui.petPlayBtn.innerHTML = label;
    }
    setHudAttr(ui.petPlayBtn, "title", destroyed
      ? "Réparer le REX — 10 000 crédits"
      : outOfFuel
        ? "+100 essence — 10 000 crédits (sans activer le REX)"
        : shownActive ? "Désactiver le P.E.T" : "Activer le P.E.T");
    setHudClass(ui.petPlayBtn, "isOn", shownActive);
  }
  // Menu custom Mode (+ gears équipés, noms boutique, un seul choix actif).
  if (ui.petModeBtn && ui.petModeList) {
    const mode = normalizePetMode(pet?.mode);
    const equipped = has ? petEquippedGearOptions() : [];
    // Gears à cooldown (TRA, FS, KK, HPL, bouées) : option grisée + compte à rebours.
    const cdLeft = { tra: Math.ceil(traCooldownLeftSec()), fs: Math.ceil(fsCooldownLeftSec()), kk: Math.ceil(kkCooldownLeftSec()), hpl: Math.ceil(hplCooldownLeftSec()), bc: Math.ceil(buoyCooldownLeftSec("bc")), bh: Math.ceil(buoyCooldownLeftSec("bh")) };
    const opts = [{ value: "passive", label: "Passif" }, { value: "combat", label: "Combat" }]
      .concat(equipped.map((e) => {
        const left = Number(cdLeft[e.key]) || 0;
        const short = shortGearLabel(e.label);
        return {
          value: `gear:${e.key}`,
          label: left > 0 ? `${short} (${left} s)` : short,
          disabled: left > 0,
        };
      }));
    const activeKey = petActiveGearKey();
    const want = activeKey ? `gear:${activeKey}` : mode;
    const wantOpt = opts.find((o) => o.value === want) || opts[0];
    // Libellés inclus : le compte à rebours (Xs) reconstruit chaque seconde.
    const sig = `${mode}|${opts.map((o) => `${o.value}=${o.label}`).join(",")}`;
    if (sig !== lastPetModeSig) {
      lastPetModeSig = sig;
      ui.petModeList.innerHTML = opts.map((o) =>
        `<button type="button" data-value="${escapeHtml(o.value)}"${o.disabled ? " disabled" : ""}>${escapeHtml(o.label)}</button>`
      ).join("");
    }
    for (const b of ui.petModeList.querySelectorAll("button[data-value]")) {
      b.classList.toggle("isCurrent", b.dataset.value === wantOpt.value);
    }
    if (ui.petModeBtn.textContent !== wantOpt.label) ui.petModeBtn.textContent = wantOpt.label;
  }
  // Liste des NPC de la carte : visible uniquement si le localisateur est actif.
  const showPetNpc = has && pet?.active === true && petActiveGearKey() === "el";
  if (ui.petNpcRow) ui.petNpcRow.hidden = !showPetNpc;
  if (!showPetNpc) {
    if (petLocator.manualType != null || petLocator.enemyId != null) {
      petLocator.manualType = null;
      petLocator.enemyId = null;
    }
    if (ui.petNpcList) ui.petNpcList.hidden = true;
  } else if (ui.petNpcBtn && ui.petNpcList) {
    const live = enemies.filter((e) => e && Number(e.hp) > 0);
    // Une entrée par famille présente sur la carte.
    const families = [...new Set(live.map((e) => String(e.type || "?")))].sort();
    if (petLocator.manualType != null && !families.includes(petLocator.manualType)) {
      petLocator.manualType = null;
      petLocator.needsPick = true;
    }
    // Défaut : une famille au hasard dans la liste.
    if (petLocator.manualType == null && petLocator.needsPick && families.length) {
      petLocator.needsPick = false;
      petLocator.manualType = families[Math.floor(Math.random() * families.length)];
    }
    const sig = families.join("|");
    if (sig !== lastPetNpcSig) {
      lastPetNpcSig = sig;
      ui.petNpcList.innerHTML = '<button type="button" data-value="">— Choisir un NPC —</button>'
        + families.map((type) => `<button type="button" data-value="${escapeHtml(type)}">${escapeHtml(String(NPC_TYPES[type]?.name || type))}</button>`).join("");
    }
    const wantNpc = petLocator.manualType != null ? String(petLocator.manualType) : "";
    for (const b of ui.petNpcList.querySelectorAll("button[data-value]")) {
      b.classList.toggle("isCurrent", (b.dataset.value || "") === wantNpc);
    }
    const wantLabel = petLocator.manualType != null
      ? String(NPC_TYPES[petLocator.manualType]?.name || petLocator.manualType)
      : "— Choisir un NPC —";
    if (ui.petNpcBtn.textContent !== wantLabel) ui.petNpcBtn.textContent = wantLabel;
  }
  // Menus flottants : suivent la fenêtre (drag), fermés sans P.E.T.
  if (!has) {
    if (ui.petModeList) ui.petModeList.hidden = true;
    if (ui.petNpcList) ui.petNpcList.hidden = true;
  } else {
    placePetDropdown(ui.petModeBtn, ui.petModeList);
    if (showPetNpc) placePetDropdown(ui.petNpcBtn, ui.petNpcList);
    else if (ui.petNpcList) ui.petNpcList.hidden = true;
  }
  // Cargo Trader (G-TRA) : expiration des 10 s ou fermeture manuelle → cooldown.
  if (petTrader.until > 0 && (!isOreTradeWindowOpen() || !traWindowActive())) endTraSession();
  // Lien HP (G-HPL) : fin des 20 s, REX désactivé ou config changée → coupure.
  if (petLink.until > 0) {
    if (performance.now() / 1000 >= petLink.until) endHplLink("expired");
    else if (account.user?.pet?.active !== true) endHplLink("off");
    else if (petConfigKey() !== petLink.configKey) endHplLink("config");
  }
  // Bouées (G-BC / G-BH) : fin des 120 s ou REX désactivé → coupure. Aura PV.
  // Config changée : on garde si la bouée est équipée sur les 2, sinon coupée.
  // (L'IEM ne coupe jamais la bouée.)
  if (petBuoy.until > 0) {
    if (performance.now() / 1000 >= petBuoy.until) endBuoySession("expired");
    else if (account.user?.pet?.active !== true) endBuoySession("off");
    else if (petConfigKey() !== petBuoy.configKey) {
      if (Number(petGearLevels()[petBuoy.key]) > 0) petBuoy.configKey = petConfigKey();
      else endBuoySession("config");
    }
  }
  tickBuoyHpAura();
  // Sprite de la fenêtre suit le palier de niveau (sans recharger en boucle).
  const stage = has ? getPetStage(level) : 0;
  if (stage !== lastPetHudStage) {
    lastPetHudStage = stage;
    if (ui.petSprite && stage > 0) {
      setHudAttr(ui.petSprite, "src", `${getPetStageBase(level)}21.png`);
      ui.petSprite.style.background = stage >= 6
        ? 'url("/PET/PET_SPRITES/NIVEAU5/21.png") center / contain no-repeat'
        : "";
    }
  }
}

let lastPetHudStage = 0;
let lastPetModeSig = "";
let lastPetNpcSig = "";
let lastPetPlaySig = "";

let selectedCraftingRecipeId = CRAFTING_RECIPES[0]?.id || null;

// Fenêtre fermée = zéro calcul (même logique que la carte stellaire) :
// test DOM gratuit d'abord, gestionnaire ensuite seulement si ouvert.
function isCraftingOpen() {
  try {
    const el = document.getElementById("craftingWindow");
    if (!el) return false;
    if (el.style.display === "none") return false;
    if (el.classList.contains("gameWinMinimized") || el.classList.contains("gameWinClosing")) return false;
    const manager = window.GameWindowManager;
    if (manager?.isOpen) {
      try { if (!manager.isOpen('craftingWindow')) return false; } catch {}
    }
    return true;
  } catch { return false; }
}

function craftingResourceAmount(user, resourceId) {
  return Math.max(0, Number(user?.inventory?.resources?.[resourceId] || 0));
}

const CRAFTING_LOGDISK_ICON = "/ASSETS/CPU/LOGFILE_100X100.png";

function craftingItemAmount(user, catalogItemId) {
  return Math.max(0, Math.floor(Number(user?.inventory?.counts?.[catalogItemId] || 0)));
}

function craftingLogDiskAmount(user) {
  return Math.max(0, Math.floor(Number(user?.pilotSkills?.disks || 0)));
}

// Munitions live (player.ammo), repli sur la sauvegarde.
function craftingAmmoAmount(user, ammoId) {
  const id = String(ammoId || "");
  if (!id) return 0;
  try {
    if (typeof player !== "undefined" && player && player.ammo && Number.isFinite(Number(player.ammo[id]))) {
      return Math.max(0, Math.floor(Number(player.ammo[id]) || 0));
    }
  } catch {}
  return Math.max(0, Math.floor(Number(user?.ammo?.[id] || 0)));
}

const CRAFTING_AMMO_NAMES = { x1: "LCB-10", x2: "MCB-25", x3: "MCB-50", x4: "UCB-100", x6: "RSB-75", sab: "SAB-50", rcb: "RCB-140", cbo: "CBO-100", job: "JOB-100", rb: "RB-214", pib: "PIB-100", idb: "IDB-125", vb: "VB-142", emaa: "EMAA-20", sbl: "SBL-100", abl: "A-BL" };
function craftingAmmoName(ammoId) {
  const id = String(ammoId || "");
  return CRAFTING_AMMO_NAMES[id] || `Munitions ${id.toUpperCase()}`;
}

function craftingRecipeDescription(recipe) {
  if (recipe.description) return recipe.description;
  const output = recipe.output || {};
  const itemId = Object.keys(output.items || {})[0];
  if (itemId) {
    const item = findCatalogItem(itemId);
    if (item?.desc) return item.desc;
    if (itemId.startsWith("booster_")) return getBooster(itemId.slice(8))?.desc || "";
  }
  const ammoId = Object.keys(output.ammo || {})[0];
  if (ammoId) return findCatalogItem(`ammo_${ammoId}`)?.desc || "Munitions pour les canons laser.";
  const rocketId = Object.keys(output.rockets || {})[0];
  if (rocketId) return findCatalogItem(`rocket_${rocketId}`)?.desc || "Munitions pour le lanceur de roquettes.";
  const shipId = Object.keys(output.ships || {})[0];
  if (shipId) {
    const info = getShipBonusInfo(shipId);
    return [info?.effet, info?.competence].filter(Boolean).join(" · ") || "Vaisseau à équiper dans le hangar.";
  }
  if (output.pet) return "Compagnon de combat et de collecte, à équiper de matériel P.E.T.";
  if (output.drones) return "Drone à deux emplacements pour lasers et générateurs de bouclier.";
  if (output.formations) return "Formation de drones modifiant les bonus de votre vaisseau.";
  return "Composant utilisé dans les recettes d’assemblage.";
}

// Un craft est faisable : crédits + ressources + objets + disques de log + munitions.
function canAffordCraftingRecipe(user, recipe, quantity = 1) {
  if (Number(user?.credits || 0) < Number(recipe?.costs?.credits || 0) * quantity) return false;
  for (const [id, amount] of Object.entries(recipe?.costs?.resources || {})) {
    if (craftingResourceAmount(user, id) < Number(amount) * quantity) return false;
  }
  for (const [id, amount] of Object.entries(recipe?.costs?.items || {})) {
    if (craftingItemAmount(user, id) < Number(amount) * quantity) return false;
  }
  for (const [id, amount] of Object.entries(recipe?.costs?.ammo || {})) {
    if (craftingAmmoAmount(user, id) < Number(amount) * quantity) return false;
  }
  if (craftingLogDiskAmount(user) < Math.max(0, Math.floor(Number(recipe?.costs?.logDisks || 0))) * quantity) return false;
  return true;
}

const CRAFTING_FALLBACK_ICON = "/ASSETS/CPU/MICRO_TRANSISTORS_100X100.png";

function craftingAmmoIcon(ammoId) {
  const key = String(ammoId || "").toUpperCase();
  return `/ASSETS/ITEMS/AMMO_${key}.png`;
}

// Vignette d'un vaisseau (même frame que les enchères).
function craftingShipIcon(shipId) {
  try {
    const pack = getShipPackByIdData(shipId);
    if (!pack) return CRAFTING_FALLBACK_ICON;
    const frames = Math.max(1, Number(pack.frames || 1));
    const base = String(pack.path || "");
    const absBase = base.startsWith("/") ? base : `/${base}`;
    return `${absBase}${Number(pack.firstNumber || 1) + (28 % frames)}${pack.ext || ".png"}`;
  } catch {
    return CRAFTING_FALLBACK_ICON;
  }
}

function craftingShipName(shipId) {
  try {
    return getShipPackByIdData(shipId)?.name || String(shipId || "Vaisseau");
  } catch {
    return String(shipId || "Vaisseau");
  }
}

function craftingItemIcon(catalogItemId) {
  const item = catalogItemId ? findCatalogItem(catalogItemId) : null;
  if (item?.icon) return item.icon;
  const id = String(catalogItemId || "");
  if (id.startsWith("booster_")) {
    try { return getBooster(id.slice("booster_".length))?.icon || CRAFTING_FALLBACK_ICON; } catch { return CRAFTING_FALLBACK_ICON; }
  }
  if (id.startsWith("ammo_")) return craftingAmmoIcon(id.slice(5));
  if (id.startsWith("rocket_")) {
    try { return rocketShopIcon(id.slice(7)) || CRAFTING_FALLBACK_ICON; } catch { return CRAFTING_FALLBACK_ICON; }
  }
  if (id.startsWith("laser_")) return `/ASSETS/LASERS/${id.slice(6)}_100x100.png`;
  if (id.startsWith("spd_") || id.startsWith("shd_")) return `/ASSETS/ITEMS/${id.slice(4).toUpperCase()}.png`;
  return CRAFTING_FALLBACK_ICON;
}

function craftingRecipeMainIcon(recipe) {
  const out = recipe?.output || {};
  const resId = Object.keys(out.resources || {})[0];
  if (resId) return getResourceIcon(resId);
  const ammoId = Object.keys(out.ammo || {})[0];
  if (ammoId) return craftingAmmoIcon(ammoId);
  const rocketId = Object.keys(out.rockets || {})[0];
  if (rocketId) {
    try { return rocketShopIcon(rocketId) || CRAFTING_FALLBACK_ICON; } catch { return CRAFTING_FALLBACK_ICON; }
  }
  const droneType = Object.keys(out.drones || {})[0];
  if (droneType) {
    try { return getDroneShopSpritePath(droneType) || CRAFTING_FALLBACK_ICON; } catch { return CRAFTING_FALLBACK_ICON; }
  }
  const formationId = Object.keys(out.formations || {})[0];
  if (formationId) {
    const formation = DRONE_FORMATIONS.find(entry => entry.id === formationId);
    if (formation?.icon) return formation.icon;
  }
  const shipId = Object.keys(out.ships || {})[0];
  if (shipId) return craftingShipIcon(shipId);
  const itemId = Object.keys(out.items || {})[0] || recipe?.catalogItemId;
  if (itemId) return craftingItemIcon(itemId);
  const petCatalogId = Object.keys(out.pet || {})[0];
  if (petCatalogId) {
    try { return findCatalogItem(petCatalogId)?.icon || CRAFTING_FALLBACK_ICON; } catch { return CRAFTING_FALLBACK_ICON; }
  }
  return CRAFTING_FALLBACK_ICON;
}

function getCraftingOwnershipBlock(user, recipe, quantity = 1) {
  for (const shipId of Object.keys(recipe?.output?.ships || {})) {
    if (user?.inventory?.ships?.includes(shipId)) return "Vaisseau déjà possédé.";
  }
  for (const formationId of Object.keys(recipe?.output?.formations || {})) {
    if (user?.drones?.formations?.includes(formationId)) return "Formation déjà possédée.";
  }
  for (const [type, unitAmount] of Object.entries(recipe?.output?.drones || {})) {
    const definition = DRONE_TYPES[type];
    const owned = (user?.drones?.items || []).filter(drone => drone?.type === type).length;
    if (!definition || owned + Number(unitAmount || 0) * quantity > definition.maxOwned) {
      return `Limite de ${definition?.name || type} atteinte.`;
    }
  }
  for (const petId of Object.keys(recipe?.output?.pet || {})) {
    if (user?.pet?.owned === true) return "P.E.T déjà possédé.";
  }
  return "";
}

function describeCraftingCosts(user, recipe, quantity) {
  const rows = Object.entries(recipe.costs?.resources || {}).map(([id, amount]) => {
    const required = Number(amount) * quantity;
    const owned = craftingResourceAmount(user, id);
    const ok = owned >= required;
    return `<li class="assemblyCostRow${ok ? " enough" : " missing"}">`
      + `<img src="${escapeHtml(getResourceIcon(id))}" alt="" loading="lazy" onerror="this.onerror=null;this.src='${CRAFTING_FALLBACK_ICON}'">`
      + `<span class="assemblyCostMeta"><span class="assemblyCostName">${escapeHtml(getResourceName(id, required))}</span></span>`
      + `<strong>${formatInteger(owned)} / ${formatInteger(required)}</strong></li>`;
  });
  const itemRows = Object.entries(recipe.costs?.items || {}).map(([id, amount]) => {
    const required = Number(amount) * quantity;
    const owned = craftingItemAmount(user, id);
    const ok = owned >= required;
    const def = findCatalogItem(id);
    return `<li class="assemblyCostRow${ok ? " enough" : " missing"}">`
      + `<img src="${escapeHtml(craftingItemIcon(id))}" alt="" loading="lazy" onerror="this.onerror=null;this.src='${CRAFTING_FALLBACK_ICON}'">`
      + `<span class="assemblyCostMeta"><span class="assemblyCostName">${escapeHtml(def?.name || id)}</span></span>`
      + `<strong>${formatInteger(owned)} / ${formatInteger(required)}</strong></li>`;
  });
  const logDiskRequired = Math.max(0, Math.floor(Number(recipe.costs?.logDisks || 0))) * quantity;  const logDiskRows = logDiskRequired > 0 ? (() => {
    const owned = craftingLogDiskAmount(user);
    const ok = owned >= logDiskRequired;
    return [`<li class="assemblyCostRow${ok ? " enough" : " missing"}">`
      + `<img src="${escapeHtml(CRAFTING_LOGDISK_ICON)}" alt="" loading="lazy" onerror="this.onerror=null;this.src='${CRAFTING_FALLBACK_ICON}'">`
      + `<span class="assemblyCostMeta"><span class="assemblyCostName">Disques de log</span></span>`
      + `<strong>${formatInteger(owned)} / ${formatInteger(logDiskRequired)}</strong></li>`];
  })() : [];
  rows.push(...itemRows, ...logDiskRows);
  const ammoRows = Object.entries(recipe.costs?.ammo || {}).map(([id, amount]) => {
    const required = Number(amount) * quantity;
    const owned = craftingAmmoAmount(user, id);
    const ok = owned >= required;
    return `<li class="assemblyCostRow${ok ? " enough" : " missing"}">`
      + `<img src="${escapeHtml(craftingAmmoIcon(id))}" alt="" loading="lazy" onerror="this.onerror=null;this.src='${CRAFTING_FALLBACK_ICON}'">`
      + `<span class="assemblyCostMeta"><span class="assemblyCostName">Munitions ${escapeHtml(craftingAmmoName(id))}</span></span>`
      + `<strong>${formatInteger(owned)} / ${formatInteger(required)}</strong></li>`;
  });
  rows.push(...ammoRows);
  const creditRequired = Number(recipe.costs?.credits || 0) * quantity;
  const creditOwned = Number(user.credits || 0);
  const creditOk = creditOwned >= creditRequired;
  rows.push(`<li class="assemblyCostRow${creditOk ? " enough" : " missing"}">`
    + `<span class="assemblyCreditIcon">¢</span>`
    + `<span class="assemblyCostMeta"><span class="assemblyCostName">Crédits</span></span>`
    + `<strong>${formatInteger(creditOwned)} / ${formatInteger(creditRequired)}</strong></li>`);
  return rows.join("");
}

function describeCraftingOutputRow(icon, label, amount) {
  return `<li class="assemblyResultRow">`
    + `<img src="${escapeHtml(icon)}" alt="" loading="lazy" onerror="this.onerror=null;this.src='${CRAFTING_FALLBACK_ICON}'">`
    + `<span>${escapeHtml(label)}</span><strong>×${formatInteger(amount)}</strong></li>`;
}

function describeCraftingOutputs(recipe, quantity) {
  const out = recipe?.output || {};
  const rows = [];
  for (const [id, amount] of Object.entries(out.resources || {})) {
    rows.push(describeCraftingOutputRow(getResourceIcon(id), getResourceName(id, Number(amount) * quantity), Number(amount) * quantity));
  }
  for (const [id, amount] of Object.entries(out.ammo || {})) {
    rows.push(describeCraftingOutputRow(craftingAmmoIcon(id), `Munitions ${String(id).toUpperCase()}`, Number(amount) * quantity));
  }
  for (const [id, amount] of Object.entries(out.rockets || {})) {
    let icon = CRAFTING_FALLBACK_ICON;
    try { icon = rocketShopIcon(id) || CRAFTING_FALLBACK_ICON; } catch { /* noop */ }
    const def = ROCKET_TYPES[id];
    rows.push(describeCraftingOutputRow(icon, def?.name || `Roquette ${id}`, Number(amount) * quantity));
  }
  for (const [id, amount] of Object.entries(out.items || {})) {
    rows.push(describeCraftingOutputRow(craftingItemIcon(id), findCatalogItem(id)?.name || id, Number(amount) * quantity));
  }
  for (const [type, amount] of Object.entries(out.drones || {})) {
    let icon = CRAFTING_FALLBACK_ICON;
    try { icon = getDroneShopSpritePath(type) || CRAFTING_FALLBACK_ICON; } catch { /* noop */ }
    rows.push(describeCraftingOutputRow(icon, `Drone ${DRONE_TYPES[type]?.name || String(type).toUpperCase()}`, Number(amount) * quantity));
  }
  for (const [id, amount] of Object.entries(out.formations || {})) {
    const formation = DRONE_FORMATIONS.find(entry => entry.id === id);
    rows.push(describeCraftingOutputRow(formation?.icon || CRAFTING_FALLBACK_ICON, formation?.name || `Formation ${id}`, Number(amount) * quantity));
  }
  for (const [id, amount] of Object.entries(out.pet || {})) {
    const def = findCatalogItem(id);
    rows.push(describeCraftingOutputRow(def?.icon || CRAFTING_FALLBACK_ICON, def?.name || "P.E.T", Number(amount) * quantity));
  }
  for (const [id, amount] of Object.entries(out.ships || {})) {
    rows.push(describeCraftingOutputRow(craftingShipIcon(id), craftingShipName(id), Number(amount) * quantity));
  }
  return rows.join("");
}

function renderCraftingWindow(message = "") {
  // Assemblage coupé (CRAFTING_ENABLED=false) : on masque la fenêtre.
  if (!CRAFTING_ENABLED) {
    document.getElementById("craftingWindow")?.style.setProperty("display", "none", "important");
    window.GameWindowManager?.close?.("craftingWindow");
    if (ui.craftingMessage) ui.craftingMessage.textContent = "Assemblage désactivé.";
    if (ui.craftingBuildBtn) ui.craftingBuildBtn.disabled = true;
    return;
  }
  // Fenêtre fermée = zéro calcul en mode téléphone : le rendu ne se fait
  // qu'à l'ouverture (même logique que la carte stellaire). Test DOM
  // gratuit d'abord, pour éviter toute lecture localStorage quand c'est fermé.
  if (isPhoneMode() && !isCraftingOpen()) return;
  if (!ui.craftingRecipes || !ui.craftingDetail) return;
  const user = getCurrentUserFull();
  if (!user) return;
  account.user = user;
  const quantity = Math.max(1, Number(ui.craftingQuantity?.value || 1));
  const RARITY_RANK = { common: 0, rare: 1, epic: 2, legendary: 3 };
  const visibleRecipes = CRAFTING_RECIPES.filter(recipe => (RARITY_RANK[recipe.rarity] ?? 0) >= 1);
  if (!visibleRecipes.some(entry => entry.id === selectedCraftingRecipeId)) {
    selectedCraftingRecipeId = visibleRecipes[0]?.id || CRAFTING_RECIPES[0]?.id || null;
  }
  // Bandeau haut : images seules, scroll horizontal.
  const recipeButtons = [...ui.craftingRecipes.children];
  const rebuildStrip = recipeButtons.length !== visibleRecipes.length
    || visibleRecipes.some((recipe, index) => recipeButtons[index]?.dataset.recipeId !== recipe.id);
  if (!visibleRecipes.length) {
    ui.craftingRecipes.innerHTML = `<div class="assemblyEmpty"><b>Aucune recette pour le moment</b></div>`;
  } else if (rebuildStrip) {
    const scrollLeft = ui.craftingRecipes.scrollLeft;
    ui.craftingRecipes.innerHTML = visibleRecipes.map(recipe => {
      const rarity = ITEM_RARITIES[recipe.rarity] || ITEM_RARITIES.common;
      const ownershipBlock = getCraftingOwnershipBlock(user, recipe, 1);
      const icon = craftingRecipeMainIcon(recipe);
      const affordable = canAffordCraftingRecipe(user, recipe, 1);
      return `<button type="button" role="option" aria-selected="${recipe.id === selectedCraftingRecipeId ? "true" : "false"}" class="assemblyThumb rarity-${rarity.id}${recipe.id === selectedCraftingRecipeId ? " active" : ""}${ownershipBlock ? " ownedLimit" : ""}${affordable && !ownershipBlock ? "" : " cantAfford"}" data-recipe-id="${escapeHtml(recipe.id)}" title="${escapeHtml(recipe.name)}">`
        + `<img src="${escapeHtml(icon)}" alt="${escapeHtml(recipe.name)}" loading="lazy" draggable="false" onerror="this.onerror=null;this.src='${CRAFTING_FALLBACK_ICON}'"></button>`;
    }).join("");
    ui.craftingRecipes.scrollLeft = scrollLeft;
  } else {
    // Les mises a jour du profil, de quantite et d'achat conservent les
    // boutons : ni le defilement du bandeau ni son focus ne sont perdus.
    visibleRecipes.forEach((recipe, index) => {
      const button = recipeButtons[index];
      const selected = recipe.id === selectedCraftingRecipeId;
      const ownershipBlock = getCraftingOwnershipBlock(user, recipe, 1);
      const affordable = canAffordCraftingRecipe(user, recipe, 1);
      button.classList.toggle('active', selected);
      button.classList.toggle('ownedLimit', Boolean(ownershipBlock));
      button.classList.toggle('cantAfford', !affordable || Boolean(ownershipBlock));
      button.setAttribute('aria-selected', String(selected));
    });
  }
  const recipe = CRAFTING_RECIPES.find(entry => entry.id === selectedCraftingRecipeId) || visibleRecipes[0];
  if (!recipe) {
    if (ui.craftingDetail) ui.craftingDetail.innerHTML = `<div class="assemblyDetailCard"><div class="assemblyEmpty"><b>En attente de recettes</b><span>Dès qu'une recette existe, son coût et son résultat s'affichent ici.</span></div></div>`;
    if (ui.craftingBuildBtn) ui.craftingBuildBtn.disabled = true;
    if (ui.craftingQuantity) ui.craftingQuantity.disabled = true;
    if (ui.craftingMessage) ui.craftingMessage.textContent = message || "Aucune recette pour le moment.";
    return;
  }
  selectedCraftingRecipeId = recipe.id;
  const rarity = ITEM_RARITIES[recipe.rarity] || ITEM_RARITIES.common;
  const costs = describeCraftingCosts(user, recipe, quantity);
  const outputs = describeCraftingOutputs(recipe, quantity);
  const mainIcon = craftingRecipeMainIcon(recipe);
  const description = craftingRecipeDescription(recipe);
  ui.craftingDetail.innerHTML = `<div class="assemblyDetailCard rarity-${rarity.id}">`
    + `<div class="assemblyDetailHead">`
    + `<img class="assemblyMainIcon" src="${escapeHtml(mainIcon)}" alt="" loading="lazy" draggable="false" onerror="this.onerror=null;this.src='${CRAFTING_FALLBACK_ICON}'">`
    + `<div class="assemblyTitleRow"><span class="assemblyRarity">${escapeHtml(rarity.name)}</span><h3>${escapeHtml(recipe.name)}</h3></div>`
    + `<p class="assemblyDescription" title="${escapeHtml(description)}">${escapeHtml(description)}</p></div>`
    + `<div class="assemblyCols"><div class="assemblySubCard"><h4>Coût ×${formatInteger(quantity)}</h4><ul class="assemblyCosts">${costs}</ul></div>`
    + `<div class="assemblySubCard"><h4>Résultat ×${formatInteger(quantity)}</h4><ul class="assemblyResults">${outputs}</ul></div></div>`
    + `</div>`;
  const canAfford = canAffordCraftingRecipe(user, recipe, quantity);
  const ownershipBlock = getCraftingOwnershipBlock(user, recipe, quantity);
  if (ui.craftingBuildBtn) ui.craftingBuildBtn.disabled = !canAfford || Boolean(ownershipBlock);
  if (ui.craftingMessage) ui.craftingMessage.textContent = message || ownershipBlock || (!canAfford ? "Ressources insuffisantes." : "");
}

ui.craftingRecipes?.addEventListener("click", event => {
  const button = event.target.closest("[data-recipe-id]");
  if (!button) return;
  selectedCraftingRecipeId = button.dataset.recipeId;
  renderCraftingWindow();
});
// Molette sur le bandeau : défile horizontalement (la molette verticale
// ne scrollerait rien sinon, le bandeau n'ayant pas de scroll vertical).
ui.craftingRecipes?.addEventListener("wheel", event => {
  const strip = ui.craftingRecipes;
  if (!strip || strip.scrollWidth <= strip.clientWidth + 1) return;
  const delta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
  if (!delta) return;
  event.preventDefault();
  strip.scrollLeft += delta;
}, { passive: false });
ui.craftingQuantity?.addEventListener("change", () => renderCraftingWindow());
ui.craftingBuildBtn?.addEventListener("click", () => {
  if (!CRAFTING_ENABLED) return renderCraftingWindow("Assemblage désactivé.");
  const recipe = CRAFTING_RECIPES.find(entry => entry.id === selectedCraftingRecipeId);
  if (!recipe) return;
  const quantity = Math.max(1, Number(ui.craftingQuantity?.value || 1));
  const user = getCurrentUserFull();
  const ownershipBlock = getCraftingOwnershipBlock(user, recipe, quantity);
  if (ownershipBlock) return renderCraftingWindow(ownershipBlock);
  const canAfford = canAffordCraftingRecipe(user, recipe, quantity);
  if (!canAfford) return renderCraftingWindow("Ressources insuffisantes.");
  // Craft instantané : pas de timer, pas de progress bar.
  const result = craftCurrentUserRecipe(recipe.id, quantity);
  if (!result.ok) return renderCraftingWindow(result.error);
  account.user = result.user;
  try { advanceQuestProgress("craft", String(recipe.id), Math.max(1, Math.floor(Number(quantity) || 1))); } catch {}
  syncPlayerFromAccount();
  window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
  const resourceOutput = Object.entries(result.recipe.output?.resources || {})
    .map(([id, amount]) => `${formatInteger(Number(amount) * result.quantity)} ${getResourceName(id, Number(amount) * result.quantity)}`)
    .join(", ");
  const craftMessage = resourceOutput
    ? `+${resourceOutput} en soute.`
    : `${result.quantity} × ${result.recipe.name} assemblé(s).`;
  showNotification(craftMessage, 3.5, "reward", { goldTerms: [result.recipe.name] });
  renderCraftingWindow(craftMessage);
});

// ============================================================
// Raffinage minerais -> minerais nobles (ratios officiels)
// Toujours au Max : seules les recettes faisables s'affichent.
// Auto : raffinage et chargement des equipements regroupes toutes les 3 s.
// ============================================================
const refineryEquipmentPrefs = { ores: {}, cursors: {} };
const REFINERY_AUTO_INTERVAL_SEC = 3;
let refineryAutoT = 0;

function refineryEquipmentPrefsKey() {
  // Le compte du moteur est encore vide pendant le montage des fenetres.
  const id = account.user?.id || netList()[0]?.id || getCurrentUserFull()?.id || "local";
  return `orbit_refinery_equipment:${id}`;
}

function saveRefineryEquipmentPrefs() {
  try {
    localStorage.setItem(refineryEquipmentPrefsKey(), JSON.stringify({
      enabled: ui.refineryAutoUpgrades?.checked === true, ...refineryEquipmentPrefs,
    }));
  } catch {}
}

function refineryChargeEquipment({ deferSave = false, applyStats = true } = {}) {
  if (!ui.refineryAutoUpgrades?.checked || !account.user) return 0;
  const result = chargeShipUpgradesAutomatically(refineryEquipmentPrefs.ores, {
    user: account.user, cursors: refineryEquipmentPrefs.cursors, deferSave,
  });
  if (!(result.consumed > 0)) return 0;
  account.user = result.user;
  refineryEquipmentPrefs.cursors = result.cursors;
  saveRefineryEquipmentPrefs();
  if (applyStats) applyCurrentConfigStats(false, null, true);
  return result.consumed;
}

function refineryRefineAll({ refineOres = true } = {}) {
  if (!account.user) loadAccountUser();
  if (!account.user) return 0;
  // Passes répétées : une recette peut débloquer la suivante (ex : Xenomit -> Promerium).
  let total = 0;
  let charged = refineryChargeEquipment({ deferSave: true, applyStats: false });
  for (let pass = 0; refineOres && pass < 10; pass++) {
    let progress = 0;
    for (const recipe of REFINERY_RECIPES) {
      const result = refineCurrentUserOre(recipe.id, Infinity, { user: account.user, deferSave: true });
      if (result.ok) {
        account.user = result.user;
        progress += result.gained;
        // Un minerai choisi pour l'equipement sert d'abord a le charger,
        // avant qu'une recette suivante ne le transforme en autre chose.
        charged += refineryChargeEquipment({ deferSave: true, applyStats: false });
      }
    }
    total += progress;
    if (progress <= 0) break;
  }
  // Une collecte peut declencher toute une chaine de recettes : persiste
  // une seule fois, sans reconstruire l'equipement entre chaque recette.
  if (total > 0 || charged > 0) saveUser(account.user, { source: "progress" });
  if (charged > 0) applyCurrentConfigStats(false, null, true);
  return total;
}

function maybeRefineryAuto() {
  if (!ui.refineryAuto?.checked && !ui.refineryAutoUpgrades?.checked) return 0;
  return refineryRefineAll({ refineOres: ui.refineryAuto?.checked === true });
}

function tickRefineryAuto(dt) {
  if (!started || (!ui.refineryAuto?.checked && !ui.refineryAutoUpgrades?.checked)) {
    refineryAutoT = 0;
    return;
  }
  refineryAutoT += Math.max(0, Number(dt) || 0);
  if (refineryAutoT < REFINERY_AUTO_INTERVAL_SEC) return;
  refineryAutoT %= REFINERY_AUTO_INTERVAL_SEC;
  maybeRefineryAuto();
}

function renderRefineryWindow(message = "") {
  if (!ui.refineryRecipes || !ui.refineryStock) return;
  const user = account.user || getCurrentUserFull();
  if (!user) return;
  account.user = user;
  const resources = user.inventory?.resources || {};
  const upgrades = user.upgrades || {};
  // Anti-flash : on ne reconstruit que si les stocks ont vraiment changé.
  const sig = ["prometium", "endurium", "terbium", "prometid", "duranium", "promerium", "seprom", "xenomit", "palladium", "osmium"]
    .map(id => `${id}:${Math.floor(Number(resources[id]) || 0)}`).join(",")
    + "|upg:" + ["laser", "rocket", "speed", "shield"].map(slot => `${slot}:${upgrades[slot]?.ore || "-"}:${Math.floor(Number(upgrades[slot]?.stock) || 0)}`).join(",")
    + "|auto:" + UPGRADE_SLOTS.map(slot => `${slot.id}:${refineryEquipmentPrefs.ores[slot.id] || ""}`).join(",");
  if (ui.refineryWindow && ui.refineryWindow.dataset.stockSig === sig) return;
  if (ui.refineryWindow) ui.refineryWindow.dataset.stockSig = sig;
  const stockIds = ["palladium", "prometium", "endurium", "terbium", "prometid", "duranium", "promerium", "seprom", "xenomit", "osmium"];
  ui.refineryStock.innerHTML = stockIds.map(id =>
    `<span class="refineryOre" draggable="true" data-ore-drag="${escapeHtml(id)}" title="Glisser vers un slot d'amélioration"><img src="${escapeHtml(getResourceIcon(id))}" alt="${escapeHtml(getResourceName(id))}" loading="lazy" draggable="false"><b>${formatInteger(resources[id] || 0)}</b></span>`
  ).join("");
  const rows = [];
  for (const recipe of REFINERY_RECIPES) {
    const { quantity } = refineOreOutput(resources, recipe, Infinity);
    if (quantity <= 0) continue;
    const inputs = Object.entries(recipe.inputs).map(([id, perUnit]) =>
      `<span class="refineryOre"><img src="${escapeHtml(getResourceIcon(id))}" alt="${escapeHtml(getResourceName(id))}" loading="lazy"><b>${formatInteger(Number(perUnit) * quantity)} / ${formatInteger(resources[id] || 0)}</b></span>`
    ).join(`<em class="refineryPlus">+</em>`);
    const output = `<span class="refineryOre out"><img src="${escapeHtml(getResourceIcon(recipe.output.id))}" alt="${escapeHtml(getResourceName(recipe.output.id))}" loading="lazy"><b>+${formatInteger(Number(recipe.output.amount) * quantity)}</b></span>`;
    rows.push(`<div class="refineryRow">${inputs}<em class="refineryArrow">→</em>${output}<button type="button" data-refinery-build="${escapeHtml(recipe.id)}">Raffiner</button></div>`);
  }
  ui.refineryRecipes.innerHTML = rows.length ? rows.join("") : `<div class="refineryEmpty">Rien à raffiner pour le moment.</div>`;
  // Largeur adaptative : on grandit (jamais on rétrécit) pour englober le contenu, sans scroll.
  if (ui.refineryWindow && ui.refineryWindow.style.display !== "none") {
    const need = Math.max(ui.refineryStock?.scrollWidth || 0, ui.refineryRecipes?.scrollWidth || 0) + 26;
    const have = ui.refineryWindow.clientWidth || 0;
    const cap = Math.min(1200, window.innerWidth - 24);
    if (need > have + 1) {
      ui.refineryWindow.style.width = `${Math.min(Math.ceil(need), cap)}px`;
      const rect = ui.refineryWindow.getBoundingClientRect();
      if (rect.right > window.innerWidth - 8) {
        ui.refineryWindow.style.left = `${Math.max(8, window.innerWidth - 8 - rect.width)}px`;
      }
    }
  }
  // Améliorations d'équipement : cartes avec slot drag & drop.
  if (ui.refineryUpgrades) {
    // Garder les select en place, meme quand un tir ou une collecte change
    // les compteurs : la liste ouverte et le focus ne doivent pas sauter.
    if (ui.refineryUpgrades.querySelectorAll(".upgCard").length !== UPGRADE_SLOTS.length) ui.refineryUpgrades.innerHTML = UPGRADE_SLOTS.map(slot => {
      const loaded = upgrades[slot.id] || {};
      const stock = Math.max(0, Math.floor(Number(loaded.stock) || 0));
      const bonusPct = Math.round(Number(UPGRADE_ORE_BONUS[String(loaded.ore)]?.[slot.id] || 0) * 100);
      const slotInner = stock > 0
        ? `<img src="${escapeHtml(getResourceIcon(loaded.ore))}" alt="${escapeHtml(getResourceName(loaded.ore))}" loading="lazy" draggable="false"><b>${formatInteger(stock)}</b>`
        : `<span class="upgSlotEmpty">Vide</span>`;
      const status = stock > 0 ? `+${bonusPct}%` : "";
      return `<div class="upgCard"><span class="upgHelp" title="${escapeHtml(slot.help || "")}">?</span>`
        + `<img class="upgIcon" src="${escapeHtml(slot.icon)}" alt="${escapeHtml(slot.name)}" loading="lazy" draggable="false">`
        + `<b class="upgName">${escapeHtml(slot.name)}</b>`
        + `<div class="upgSlot${stock > 0 ? " filled" : ""}" data-upgrade-slot="${escapeHtml(slot.id)}">${slotInner}</div>`
        + `<small class="upgStatus">${escapeHtml(status)}</small>`
        + `<select class="upgAutoOre" data-upgrade-auto-ore="${escapeHtml(slot.id)}" aria-label="Raffinage auto : ${escapeHtml(slot.name)}">`
        + `<option value="">Aucun</option>`
        + UPGRADE_SLOT_ORES[slot.id].map(ore => `<option value="${escapeHtml(ore)}">${escapeHtml(getResourceName(ore))} (+${Math.round(UPGRADE_ORE_BONUS[ore][slot.id] * 100)} %)</option>`).join("")
        + `</select></div>`;
    }).join("");
    for (const slot of UPGRADE_SLOTS) {
      refreshUpgradeSlotDom(slot.id);
      const select = ui.refineryUpgrades.querySelector(`[data-upgrade-auto-ore="${slot.id}"]`);
      const value = refineryEquipmentPrefs.ores[slot.id] || "";
      if (select && select.value !== value) select.value = value;
    }
  }
}

// Le compte est initialise plus bas : restaurer les preferences apres le
// montage du moteur, avant le premier rendu des cartes.
queueMicrotask(() => { try {
  if (ui.refineryAuto) ui.refineryAuto.checked = localStorage.getItem("orbit_refinery_auto") === "1";
  const stored = JSON.parse(localStorage.getItem(refineryEquipmentPrefsKey()) || "null");
  if (stored) {
    if (ui.refineryAutoUpgrades) ui.refineryAutoUpgrades.checked = stored.enabled === true;
    for (const slot of UPGRADE_SLOTS) {
      const ore = String(stored.ores?.[slot.id] || "");
      refineryEquipmentPrefs.ores[slot.id] = UPGRADE_SLOT_ORES[slot.id].includes(ore) ? ore : "";
    }
    refineryEquipmentPrefs.cursors = stored.cursors && typeof stored.cursors === "object" ? stored.cursors : {};
  }
} catch {} });
ui.refineryAutoUpgrades?.addEventListener("change", () => {
  saveRefineryEquipmentPrefs();
  if (ui.refineryAutoUpgrades.checked) { saveProgressNow(); maybeRefineryAuto(); }
  renderRefineryWindow();
  updateResourceHud(ui, player, currentCargo());
});
ui.refineryUpgrades?.addEventListener("change", event => {
  const select = event.target.closest("[data-upgrade-auto-ore]");
  if (!select) return;
  const slot = select.dataset.upgradeAutoOre, ore = select.value;
  if (!UPGRADE_SLOT_ORES[slot] || (ore && !UPGRADE_SLOT_ORES[slot].includes(ore))) return;
  refineryEquipmentPrefs.ores[slot] = ore;
  saveRefineryEquipmentPrefs();
  if (ui.refineryAutoUpgrades?.checked) { saveProgressNow(); maybeRefineryAuto(); }
  renderRefineryWindow();
  updateResourceHud(ui, player, currentCargo());
});
ui.refineryAuto?.addEventListener("change", () => {
  try { localStorage.setItem("orbit_refinery_auto", ui.refineryAuto?.checked ? "1" : "0"); } catch {}
  if (ui.refineryAuto?.checked) {
    saveProgressNow();
    refineryRefineAll();
    renderRefineryWindow();
  } else {
    renderRefineryWindow();
  }
});

ui.refineryAllBtn?.addEventListener("click", () => {
  saveProgressNow();
  refineryRefineAll();
  renderRefineryWindow();
  try { if (ui.oreTradeWindow && ui.oreTradeWindow.style.display !== "none") renderOreTradeWindow(); } catch {}
  window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
});

ui.refineryRecipes?.addEventListener("click", event => {
  const button = event.target.closest("[data-refinery-build]");
  if (!button) return;
  saveProgressNow();
  const result = refineCurrentUserOre(button.dataset.refineryBuild, Infinity);
  if (!result.ok) {
    account.user = result.user || account.user;
    return renderRefineryWindow(result.error);
  }
  account.user = result.user;
  const autoTotal = maybeRefineryAuto();
  renderRefineryWindow(`${formatInteger(result.gained + autoTotal)} ${getResourceName(result.recipe.output.id, result.gained + autoTotal)} raffiné(s).`);
  try { if (ui.oreTradeWindow && ui.oreTradeWindow.style.display !== "none") renderOreTradeWindow(); } catch {}
  window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
});
ui.refineryUpgrades?.addEventListener("click", event => {
  const button = event.target.closest("[data-upgrade-charge]");
  if (!button) return;
  const slot = String(button.dataset.upgradeCharge || "");
  const select = ui.refineryUpgrades?.querySelector(`[data-upgrade-ore="${slot}"]`);
  saveProgressNow();
  const result = chargeShipUpgrade(slot, select?.value, Infinity);
  if (!result.ok) {
    account.user = result.user || account.user;
    showToast(result.error, 2);
    return;
  }
  account.user = result.user;
  applyCurrentConfigStats(false, null, true);
  renderRefineryWindow();
  try { if (ui.oreTradeWindow && ui.oreTradeWindow.style.display !== "none") renderOreTradeWindow(); } catch {}
  window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
});

// Drag & drop minerai du stock -> slot d'amélioration, puis choix de la quantité.
const UPGRADE_AMOUNT_CHOICES = Object.freeze(["max", 1, 5, 10, 50, 100, 500, 1000]);
let pendingUpgrade = null;
let pendingUpgradeAmount = "max";

function openUpgradeAmountDialog(slotId, oreId) {
  const user = account.user || getCurrentUserFull();
  const slot = UPGRADE_SLOTS.find(entry => entry.id === String(slotId || ""));
  if (!slot || !(UPGRADE_SLOT_ORES[slot.id] || []).includes(String(oreId || ""))) {
    showToast("Minerai incompatible.", 2);
    return;
  }
  const owned = Math.max(0, Math.floor(Number(user?.inventory?.resources?.[oreId]) || 0));
  if (owned <= 0) {
    showToast("Stock vide.", 2);
    return;
  }
  pendingUpgrade = { slot: slot.id, ore: String(oreId) };
  pendingUpgradeAmount = "max";
  if (ui.upgAmountIcon) ui.upgAmountIcon.src = getResourceIcon(oreId);
  if (ui.upgAmountTitle) ui.upgAmountTitle.textContent = `${slot.name} — ${getResourceName(oreId)}`;
  renderUpgradeAmountDialog();
  if (ui.upgAmountDialog) ui.upgAmountDialog.hidden = false;
}

function renderUpgradeAmountDialog() {
  if (!pendingUpgrade || !ui.upgAmountBtns) return;
  const user = account.user || getCurrentUserFull();
  const owned = Math.max(0, Math.floor(Number(user?.inventory?.resources?.[pendingUpgrade.ore]) || 0));
  const slot = UPGRADE_SLOTS.find(entry => entry.id === pendingUpgrade.slot) || {};
  const available = Math.min(owned, upgradeOreCapacity(user?.upgrades, pendingUpgrade.slot, pendingUpgrade.ore));
  ui.upgAmountBtns.innerHTML = UPGRADE_AMOUNT_CHOICES.map(n => {
    const isMax = n === "max";
    const disabled = isMax ? available <= 0 : available < n;
    const active = pendingUpgradeAmount === n ? "active" : "";
    return `<button type="button" data-upgrade-amount="${n}" class="${active}"${disabled ? " disabled" : ""}>${isMax ? "MAX" : n}</button>`;
  }).join("");
  const amount = pendingUpgradeAmount === "max" ? available : Math.min(available, pendingUpgradeAmount);
  const gives = amount * 10;
  if (ui.upgAmountPreview) ui.upgAmountPreview.textContent = `${pendingUpgradeAmount === "max" ? "MAX" : pendingUpgradeAmount} minerai → +${formatInteger(gives)} ${slot.unit || "tirs"} (stock : ${formatInteger(owned)} · plafond : ${formatInteger(UPGRADE_STOCK_MAX)})`;
  if (ui.upgAmountOk) ui.upgAmountOk.disabled = available <= 0 || (pendingUpgradeAmount !== "max" && pendingUpgradeAmount > available);
}

function closeUpgradeAmountDialog() {
  pendingUpgrade = null;
  if (ui.upgAmountDialog) ui.upgAmountDialog.hidden = true;
}

ui.refineryStock?.addEventListener("dragstart", event => {
  const source = event.target.closest("[data-ore-drag]");
  if (!source) return;
  event.dataTransfer?.setData("text/plain", String(source.dataset.oreDrag || ""));
  event.dataTransfer?.setData("application/x-ore", String(source.dataset.oreDrag || ""));
});

ui.refineryUpgrades?.addEventListener("dragover", event => {
  const slot = event.target.closest("[data-upgrade-slot]");
  if (!slot) return;
  event.preventDefault();
  slot.classList.add("dragTarget");
});

ui.refineryUpgrades?.addEventListener("dragleave", event => {
  const slot = event.target.closest("[data-upgrade-slot]");
  if (slot && !slot.contains(event.relatedTarget)) slot.classList.remove("dragTarget");
});

ui.refineryUpgrades?.addEventListener("drop", event => {
  const slot = event.target.closest("[data-upgrade-slot]");
  if (!slot) return;
  event.preventDefault();
  slot.classList.remove("dragTarget");
  const ore = event.dataTransfer?.getData("application/x-ore") || event.dataTransfer?.getData("text/plain");
  if (ore) openUpgradeAmountDialog(slot.dataset.upgradeSlot, ore);
});

ui.upgAmountBtns?.addEventListener("click", event => {
  const button = event.target.closest("[data-upgrade-amount]");
  if (!button || button.disabled) return;
  const raw = button.dataset.upgradeAmount;
  pendingUpgradeAmount = raw === "max" ? "max" : Math.max(1, Math.floor(Number(raw) || 1));
  renderUpgradeAmountDialog();
});

ui.upgAmountCancel?.addEventListener("click", closeUpgradeAmountDialog);

ui.upgAmountOk?.addEventListener("click", () => {
  if (!pendingUpgrade) return closeUpgradeAmountDialog();
  saveProgressNow();
  // La limite tient compte du stock deja charge et reste verifiee au moment
  // de la validation, meme si le raffinage auto a rempli le slot entretemps.
  const amount = pendingUpgradeAmount === "max" ? Infinity : pendingUpgradeAmount;
  const result = chargeShipUpgrade(pendingUpgrade.slot, pendingUpgrade.ore, amount);
  if (!result.ok) {
    account.user = result.user || account.user;
    showToast(result.error, 2);
    closeUpgradeAmountDialog();
    return;
  }
  account.user = result.user;
  applyCurrentConfigStats(false, null, true);
  closeUpgradeAmountDialog();
  renderRefineryWindow();
  try { if (ui.oreTradeWindow && ui.oreTradeWindow.style.display !== "none") renderOreTradeWindow(); } catch {}
  window.dispatchEvent(new CustomEvent("orbit:profile-progress"));
});
queueMicrotask(() => renderRefineryWindow());
window.addEventListener("orbit:window-restored", event => {
  if (event.detail?.id === "craftingWindow") renderCraftingWindow();
  if (event.detail?.id === "refineryWindow") renderRefineryWindow();
});
window.addEventListener("orbit:profile-progress", () => {
  if (isCraftingOpen()) renderCraftingWindow();
});
window.addEventListener("orbit:profile-progress", () => {
  // Commerce <-> raffinage synchronisés même sans action directe (collecte,
  // récompense, autre onglet...) : re-rend les fenêtres ouvertes.
  try { if (ui.refineryWindow && ui.refineryWindow.style.display !== "none") renderRefineryWindow(); } catch {}
  try { if (ui.oreTradeWindow && ui.oreTradeWindow.style.display !== "none") renderOreTradeWindow(); } catch {}
});
queueMicrotask(() => renderCraftingWindow());

let selectedGalaxyGateId = null;

function formatGalaxyGatePartRewards(reward) {
  const detailed = Object.entries(reward?.partsByGate || {})
    .filter(([, amount]) => Number(amount) > 0)
    .map(([gateId, amount]) => {
      const gateName = GALAXY_GATE_DEFINITIONS[gateId]?.name || gateId;
      return `${formatInteger(amount)} pièce${Number(amount) > 1 ? "s" : ""} ${gateName}`;
    });
  if (detailed.length) return detailed;
  const total = Math.max(0, Number(reward?.parts) || 0);
  return total ? [`${formatInteger(total)} pièce${total > 1 ? "s" : ""}`] : [];
}

function renderGalaxyGateWindow(message = "") {
  if (!ui.ggTabs) return;
  const user = getCurrentUserFull();
  const state = user?.galaxyGates;
  if (!state) return;
  if (!selectedGalaxyGateId && GALAXY_GATE_DEFINITIONS[state.lastOpenedGate]) selectedGalaxyGateId = state.lastOpenedGate;
  const gate = GALAXY_GATE_DEFINITIONS[selectedGalaxyGateId] || GALAXY_GATE_DEFINITIONS.alpha;
  ui.ggEnergy.textContent = formatInteger(state.energy);
  ui.ggCredits.textContent = formatInteger(user.credits);
  const displayedParts = state.built[gate.id] >= GALAXY_GATE_BUILD_LIMIT ? gate.requiredParts : state.parts[gate.id];
  ui.ggParts.textContent = `${formatInteger(displayedParts)} / ${formatInteger(gate.requiredParts)}`;
  ui.ggPortalImage.src = gate.image;
  ui.ggPortalImage.alt = `Portail ${gate.name}`;
  const completion = gate.completion;
  ui.ggRewards.innerHTML = `<strong>Récompenses finales</strong><span>${formatInteger(completion.exp)} XP</span><span>${formatInteger(completion.honor)} honneur</span><span>${formatInteger(completion.credits)} crédits</span><span>${formatInteger(completion.x4)} UCB-100</span>`;
  ui.ggNpcRewardScale.innerHTML = `Récompenses des NPC <em>×${gate.rewardScale}</em>`;
  // ✅ multiplicateur affiché/armé par groupe de spin (ABG vs Delta isolés).
  const ggSpinGroup = gate.group || gate.id;
  const ggGroupMultiplier = Math.min(5, Math.max(1, Number(state.multipliers?.[ggSpinGroup]) || 1));
  const ggGroupArmed = state.multiplierArmed?.[ggSpinGroup] === true;
  ui.ggMultiplier.textContent = `x${ggGroupMultiplier}`;
  if (ui.ggMultiplierBtn) {
    const armed = ggGroupArmed;
    ui.ggMultiplierBtn.disabled = ggGroupMultiplier <= 1;
    ui.ggMultiplierBtn.classList.toggle("active", armed);
    const actionLabel = ui.ggMultiplierBtn.querySelector(".ggMultiplierAction");
    if (actionLabel) actionLabel.textContent = armed ? "Activée" : "Désactivée";
  }
  const isActive = state.active === gate.id;
  const isDeployed = state.deployed?.[gate.id] === true;
  const stock = Math.max(0, Math.floor(Number(state.built[gate.id]) || 0));
  const waiting = stock > 0 ? `${formatInteger(stock)} en attente` : "";
  ui.ggBuilt.textContent = isActive
    ? ["1 en cours", waiting].filter(Boolean).join(" · ")
    : isDeployed
      ? ["1 sur la carte", waiting].filter(Boolean).join(" · ")
      : waiting || "Aucune gate construite";
  if (ui.ggCompleted) ui.ggCompleted.textContent = formatInteger(state.completed[gate.id]);
  if (ui.ggLives) ui.ggLives.textContent = `${formatInteger(state.lives?.[gate.id] ?? gate.maxLives)} / ${formatInteger(gate.maxLives)}`;
  const activeWave = state.active === gate.id
    ? Math.min(gate.maxWaves, Math.max(1, Number(state.activeWave) || 1))
    : Math.min(gate.maxWaves, Math.max(0, Number(state.waves?.[gate.id]) || 0));
  ui.ggWave.textContent = `${activeWave} / ${gate.maxWaves}`;
  const selectedSpinCount = Math.max(1, Number(ui.ggSpinCount?.value || 1));
  ui.ggCreditCost.textContent = formatInteger(GALAXY_SPIN_CREDIT_COST * selectedSpinCount);
  ui.ggSpinBtn.hidden = gate.id === "kronos";
  ui.ggSpinBtn.disabled = gate.id === "kronos";
  if (ui.ggSpinCount) ui.ggSpinCount.disabled = gate.id === "kronos";
  // ✅ plus de bouton "Préparer" : le placement sur la map est automatique.
  if (ui.ggDeployBtn) ui.ggDeployBtn.remove();
  ui.ggDeployBtn = null;
  // ✅ onglets groupés : Ensemble ABG (roue commune) séparé de Delta (roue isolée).
  const ggTabButton = (item) => {
    const parts = state.built[item.id] >= GALAXY_GATE_BUILD_LIMIT ? item.requiredParts : state.parts[item.id];
    return `<button type="button" data-gg-gate="${escapeHtml(item.id)}" class="${item.id === gate.id ? "active" : ""}">${escapeHtml(item.name)}<small>${parts}/${item.requiredParts}</small></button>`;
  };
  const ensembleTabs = Object.values(GALAXY_GATE_DEFINITIONS).filter(item => (item.group || item.id) === "ensemble").map(ggTabButton).join("");
  const deltaTabs = Object.values(GALAXY_GATE_DEFINITIONS).filter(item => (item.group || item.id) === "delta").map(ggTabButton).join("");
  const epsilonTabs = Object.values(GALAXY_GATE_DEFINITIONS).filter(item => (item.group || item.id) === "epsilon").map(ggTabButton).join("");
  const zetaTabs = Object.values(GALAXY_GATE_DEFINITIONS).filter(item => (item.group || item.id) === "zeta").map(ggTabButton).join("");
  const kappaTabs = Object.values(GALAXY_GATE_DEFINITIONS).filter(item => (item.group || item.id) === "kappa").map(ggTabButton).join("");
  const lambdaTabs = Object.values(GALAXY_GATE_DEFINITIONS).filter(item => (item.group || item.id) === "lambda").map(ggTabButton).join("");
  const kronosTabs = Object.values(GALAXY_GATE_DEFINITIONS).filter(item => item.id === "kronos").map(ggTabButton).join("");
  ui.ggTabs.innerHTML = `<div class="ggTabsGroup" data-gg-group="ensemble"><div class="ggTabsButtons">${ensembleTabs}</div></div>`
    + `<div class="ggTabsGroup" data-gg-group="delta"><div class="ggTabsButtons">${deltaTabs}</div></div>`
    + `<div class="ggTabsGroup" data-gg-group="epsilon"><div class="ggTabsButtons">${epsilonTabs}</div></div>`
    + `<div class="ggTabsGroup" data-gg-group="zeta"><div class="ggTabsButtons">${zetaTabs}</div></div>`
    + `<div class="ggTabsGroup" data-gg-group="kappa"><div class="ggTabsButtons">${kappaTabs}</div></div>`
    + `<div class="ggTabsGroup" data-gg-group="lambda"><div class="ggTabsButtons">${lambdaTabs}</div></div>`
    + `<div class="ggTabsGroup" data-gg-group="kronos"><div class="ggTabsButtons">${kronosTabs}</div></div>`;
  const history = [...state.history].reverse();
  ui.ggHistory.innerHTML = history.length ? history.map(entry => {
    const reward = entry.rewards || {};
    const applications = Array.isArray(reward.multiplierApplications) && reward.multiplierApplications.length
      ? reward.multiplierApplications
      : reward.multiplierApplied ? [reward.multiplierApplied] : [];
    const appliedTotals = applications.reduce((totals, item) => {
      const key = `${item.rewardType}:${item.rewardId || ""}`;
      totals[key] = (totals[key] || 0) + (Number(item.amount) || 0);
      return totals;
    }, {});
    const ammo = Object.entries(reward.ammo || {})
      .map(([id, amount]) => [id, Math.max(0, amount - (appliedTotals[`ammo:${id}`] || 0))])
      .filter(([, amount]) => amount > 0)
      .map(([id, amount]) => `${formatInteger(amount)} munitions ${escapeHtml(String(id).toUpperCase())}`);
    const ROCKET_REWARD_NAMES = { plt2021: "PLT-2021", plt3030: "PLT-3030", ubr100: "UBR-100", hstrm01: "HSTRM-01" };
    const rockets = Object.entries(reward.rockets || {})
      .map(([id, amount]) => [id, Math.max(0, amount - (appliedTotals[`rockets:${id}`] || 0))])
      .filter(([, amount]) => amount > 0)
      .map(([id, amount]) => `${formatInteger(amount)} roquettes ${escapeHtml(ROCKET_REWARD_NAMES[String(id).toLowerCase()] || String(id).toUpperCase())}`);
    const built = Object.entries(reward.builtByGate || {}).filter(([, amount]) => amount > 0).map(([gateId]) => `${escapeHtml(GALAXY_GATE_DEFINITIONS[gateId]?.name || gateId)} terminée`);
    const duplicateCounts = (reward.duplicates || []).reduce((counts, item) => {
      counts[item.gate] = (counts[item.gate] || 0) + 1;
      return counts;
    }, {});
    const duplicates = Object.entries(duplicateCounts).map(([gateId, amount]) => `Doublon (${escapeHtml(GALAXY_GATE_DEFINITIONS[gateId]?.name || gateId)}) +${amount} multiplicateur${amount > 1 ? "s" : ""}`);
    const groupedApplications = Object.values(applications.reduce((groups, applied) => {
      const key = `${applied.rewardType}:${applied.rewardId || ""}:x${applied.multiplier}`;
      if (!groups[key]) groups[key] = { ...applied, amount: 0, count: 0 };
      groups[key].amount += Number(applied.amount) || 0;
      groups[key].count++;
      return groups;
    }, {}));
    const appliedTexts = groupedApplications.map(applied => {
      if (applied.rewardType === "ammo") return `${formatInteger(applied.amount)} Munitions ${escapeHtml(String(applied.rewardId || "").toUpperCase())} (x${applied.multiplier})`;
      if (applied.rewardType === "rockets") return `${formatInteger(applied.amount)} Roquettes ${escapeHtml(ROCKET_REWARD_NAMES[String(applied.rewardId || "").toLowerCase()] || String(applied.rewardId || "").toUpperCase())} (x${applied.multiplier})`;
      if (applied.rewardType === "credits") return `${formatInteger(applied.amount)} Crédits (x${applied.multiplier})`;
      if (applied.rewardType === "energy") return `${formatInteger(applied.amount)} Énergies (x${applied.multiplier})`;
      if (applied.rewardType === "parts") return `Pièces ${escapeHtml(GALAXY_GATE_DEFINITIONS[applied.rewardId]?.name || applied.rewardId)} obtenues : ${formatInteger(applied.amount)} x${applied.multiplier}`;
      return "";
    }).filter(Boolean);
    const remainingCredits = Math.max(0, (reward.credits || 0) - (appliedTotals["credits:"] || 0));
    const remainingEnergy = Math.max(0, (reward.energy || 0) - (appliedTotals["energy:"] || 0));
    const remainingParts = Object.fromEntries(Object.entries(reward.partsByGate || {}).map(([gateId, amount]) => [
      gateId,
      Math.max(0, amount - (appliedTotals[`parts:${gateId}`] || 0)),
    ]));
    const credits = remainingCredits ? `${formatInteger(remainingCredits)} crédits` : "";
    const energy = remainingEnergy ? `${remainingEnergy} énergie` : "";
    const gains = [...formatGalaxyGatePartRewards({ partsByGate: remainingParts }), ...built, ...duplicates, credits, energy, ...ammo, ...rockets].filter(Boolean);
    const gainRows = (gains.length || appliedTexts.length)
      ? `${gains.map(gain => `<small>${gain}</small>`).join("")}${appliedTexts.map(text => `<small class="ggHistoryMultiplierApplied">${text}</small>`).join("")}`
      : `<small>Aucun gain direct</small>`;
    const historyGate = GALAXY_GATE_DEFINITIONS[entry.gate] || GALAXY_GATE_DEFINITIONS.alpha;
    const gateSetLabel = historyGate.group === "ensemble"
      ? Object.values(GALAXY_GATE_DEFINITIONS).filter(item => item.group === "ensemble").map(item => item.name).join(" · ")
      : historyGate.name;
    return `<div class="ggHistoryRow"><span><b>${escapeHtml(gateSetLabel)}</b> · ${Number(entry.spins) || 0} spin(s)</span><div class="ggHistoryGains">${gainRows}</div></div>`;
  }).join("") : `<div class="ggHistoryEmpty">Aucun spin enregistré.</div>`;
}

